import { Book } from "@/lib/types";

export const judges: Book = {
  id: "judges",
  name: "Richter",
  shortName: "Ri",
  testament: "old",
  introduction: `Wenn jeder tut, was er für richtig hält\n**Das Buch der Richter** ist die Fortsetzung des Buches Josua. Es fasst alles zusammen, was nach dem Tod Josuas bis zur Zeit Samuels unter 12 Richtern geschah. Seinen Namen hat es von den Führern, die militärische und richterliche Funktionen in einzelnen Stämmen, manchmal auch für ganz Israel erfüllten. Wahrscheinlich überlappen sich die Zeiten einiger Unterdrückungs- und Richterperioden. Insgesamt können je sieben Perioden der Unterdrückung und Befreiung verfolgt werden. Geistlich gesehen kann man die Zeit am besten durch die Worte in Richter 17,6 und 21,25 wiedergeben: **Damals gab es noch keinen König in Israel. Jeder tat, was er für richtig hielt.** Das Buch wurde vermutlich am Anfang der Königszeit zwischen 1040 und 1020 v.Chr. möglicherweise von Samuel geschrieben.\n****Wie sich in Israel die Perioden des Abfalls von Gott, Unterdrückung durch Fremde und Befreiung durch einen Richter immer wieder abwechselten.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Was nach dem Tod Josuas geschah.* Die Israeliten fragten Jahwe*: \"Wer von uns soll zuerst gegen die Kanaaniter* in den Kampf ziehen?\"", heading: "1-2: Hintergründe des Abfalls von Gott\nWie die Stämme Juda und Simeon ihr Gebiet eroberten", footnotes: ["Die ersten Worte sind am besten als Überschrift über das ganze Buch der Richter aufzufassen, denn der folgende Bericht wiederholt mit weiteren Einzelheiten einige Geschehnisse bis zum Tod Josuas, die schon im Buch Josua berichtet wurden.", "Jahwe. Name Gottes, der die persönliche Nähe zum Menschen ausdrückt, siehe 1. Mose 2,4.", "Kanaaniter. Bewohner des Landes Kanaan auf dem Gebiet des heutigen Israel. Sie besaßen eine gemeinsame Sprache, Religion und Kultur, waren politisch aber in viele Kleinkönigtümer und Stadtstaaten zersplittert."] },
      { number: 2, text: "Jahwe antwortete: \"Der Stamm Juda soll es tun! Ich gebe das Land in seine Gewalt.\"" },
      { number: 3, text: "Da sagten die Männer von Juda zu ihren Brüdern aus dem Stamm Simeon*: \"Kommt mit und helft uns im Kampf um das Gebiet, das uns zugeteilt worden ist! Wir werden euch dann auch im Kampf um euer Gebiet helfen.\" Da schlossen sich die Männer von Simeon Juda an.", footnotes: ["Simeon.Josua teilte dem Stamm Städte im Gebiet von Juda zu, siehe Josua 19,1-9."] },
      { number: 4, text: "Sie zogen in den Kampf und Jahwe schenkte ihnen den Sieg über die Kanaaniter und Perisiter*. Bei der Stadt Besek* schlugen sie ein Heer von 10.000 Mann.", footnotes: ["Perisiter. Bewohner Kanaans, manche verstehen sie nicht als eigenen Stamm, sondern als die Dorfbewohner.", "Besek. Ort im Stammesgebiet von Juda, vielleicht Chirbet Buzqa 6 km nordöstlich von Geser."] },
      { number: 5, text: "Dabei stießen sie auch auf deren König Adoni-Besek*. Als dieser merkte, dass sein Heer geschlagen war,", footnotes: ["Adoni-Besek. Das heißt so viel wie Herr von Besek."] },
      { number: 6, text: "floh er. Doch sie verfolgten ihn und nahmen ihn gefangen. Dann hackten sie ihm die Daumen und die beiden großen Zehen ab." },
      { number: 7, text: "Da sagte Adoni-Besek: \"Siebzig Könige* ohne Daumen und große Zehen haben unter meinem Tisch die Abfälle aufgelesen. Jetzt hat Gott mir dasselbe Schicksal bereitet.\" Seine Leute brachten ihn dann nach Jerusalem, wo er starb,", footnotes: ["Könige. Kanaan war in viele kleine Stadtstaaten aufgeteilt, die von \"Königen\" regiert wurden."] },
      { number: 8, text: "denn die Männer von Juda griffen auch Jerusalem an und eroberten es. Sie töteten die Bewohner und steckten die Stadt in Brand.*", footnotes: ["Stadt in Brand. Offenbar hatten sie nur einen Teil der Stadt, nicht die Zitadelle erobert (siehe Vers 21). Erst 400 Jahre später, zur Zeit Davids, wurde Jerusalem endgültig für die Juden erobert."] },
      { number: 9, text: "Danach kämpften sie gegen die Kanaaniter, die das Bergland bewohnten, den Negev, das heiße Land im Süden, und die Schefela, das Hügelland im Westen." },
      { number: 10, text: "Anschließend griffen sie die kanaanitischen Bewohner der Stadt Hebron* an, die damals noch Kirjat-Arba* hieß, und besiegten die Sippenverbände Scheschai, Achiman und Telmai*.", footnotes: ["Hebron. 35 km südlich von Jerusalem und 30 km westlich vom Toten Meer.", "Kirjat-Arba. Stadt der Vier, weist auf ein altes Bündnis hin, denn Hebron bedeutet auch Bündnis.", "Telmai. Nach V. 20 und 4. Mose 13,22 waren das Söhne Anaks."] },
      { number: 11, text: "Dann zogen sie gegen die Stadt Debir, die damals noch Kirjat-Sefer* hieß.", footnotes: ["Kirjat-Sefer. Stadt der Bücher (oder: der Schreiber) liegt 25 km südwestlich von Hebron."] },
      { number: 12, text: "Dort sagte Kaleb zu seinen Truppen: \"Wer Kirjat-Sefer erobert, bekommt meine Tochter Achsa zur Frau!\"*", footnotes: ["Achsa zur Frau. Der Sieg im Kampf war eine Möglichkeit, den Brautpreis zu zahlen."] },
      { number: 13, text: "Kalebs Neffe Otniel – er war der Sohn von dessen jüngerem Bruder Kenas – eroberte die Stadt. Daraufhin durfte er Achsa zur Frau nehmen." },
      { number: 14, text: "Als sie ihm zugeführt wurde, rang sie ihm die Erlaubnis ab, gleich noch ein Stück Land von ihrem Vater fordern zu dürfen. Dann glitt sie von ihrem Esel, und Kaleb fragte: \"Was hast du?\"" },
      { number: 15, text: "Sie erwiderte: \"Wenn du mich schon in den heißen Negev verheiratet hast, dann gib mir auch ein paar Wasserbecken als Segensgeschenk dazu!\" Da schenkte ihr Kaleb die oberen und die unteren Teichanlagen bei Hebron." },
      { number: 16, text: "Die Nachkommen von Moses Schwager*, – das waren Keniter – waren mit den Männern Judas aus der Palmenstadt aufgebrochen und in das Steppengebiet gezogen, das im Süden von Arad* liegt. Als Halbnomaden hielten sie sich im Gebiet Judas auf.", footnotes: ["Schwager. Manche übersetzen hier: Schwiegervater. Doch die hebr. Wurzel htn kann jede Schwiegerbeziehung meinen: Schwiegervater, Schwiegersohn, Schwager. Nach 4. Mose 10,29 war Hobab der Schwager von Mose.", "Arad. Stadt im Negev."] },
      { number: 17, text: "Dann halfen die Männer Judas ihren Stammesbrüdern von Simeon, die Kanaaniter in Zefat zu besiegen. Sie vollstreckten den Bann* an der Stadt und nannten sie Horma, Bann.", footnotes: ["Bann. Das bedeutete meistens die vollständige Vernichtung von Menschen, Tieren und Gütern."] },
      { number: 18, text: "Doch die Städte Gaza, Aschkelon und Ekron* mit den dazugehörigen Gebieten konnten die Männer Judas nicht einnehmen,", footnotes: ["... Ekron. Diese Philisterstädte bildeten mit Aschdod und Gat den Fünfstädtebund, siehe Richter 3,3."] },
      { number: 19, text: "denn die Bewohner der Küstenebene hatten eiserne Streitwagen*. So konnten sie sie nicht vertreiben. Jahwe half ihnen aber, das Bergland zu erobern.", footnotes: ["Streitwagen. Einachsige, von Pferden gezogene schnelle Wage, die von einem Wagenlenker, einem Bogeschützen und evtl. noch einem Schildhalter besetzt waren – die Panzer des Altertums."] },
      { number: 20, text: "Nach der Anordnung Moses wurde dann die Stadt Hebron Kaleb zugesprochen, der die drei Sippen der Anakssöhne* von dort vertrieben hatte.", footnotes: ["Anakssöhne. Siehe Vers 10."] },
      { number: 21, text: "Doch die Jebusiter, die Bewohner Jerusalems, wurden auch von den Männern des Stammes Benjamin nicht vertrieben.* Bis heute* leben sie dort unter den Benjaminiten.", footnotes: ["nicht vertrieben. Jerusalem lag an der Grenze des Stammesgebietes von Juda und Benjamin. Als Folge des vorher erwähnten begrenzten Sieges (V. 8) konnten sich die Jebusiter in der Stadt halten.", "Heute – meint den Zeitpunkt der Abfassung dieses Buches, der zwischen der Krönung Sauls 1050 v.Chr. und der Eroberung durch David 1004 v.Chr. liegen muss. Das Buch der Richter blickt von der Königszeit zurück, siehe z.B. Richter 17,6."] },
      { number: 22, text: "Auch die Männer der Josefstämme Efraïm und Manasse zogen los und griffen Bet-El* an. Jahwe stand ihnen bei.", heading: "Der Norden Kanaans wird nur zum Teil erobert", footnotes: ["Bet-El. Haus Gottes. Jakob hatte hier einen Altar gebaut, siehe 1. Mose 35, 1-15. Der Ort lag etwa 19 km nördlich von Jerusalem auf dem Gebirge Efraïm."] },
      { number: 23, text: "Zuerst erkundeten sie die Stadt, die damals noch Lus hieß." },
      { number: 24, text: "Als die Späher einen Mann herauskommen sahen, hielten sie ihn fest und sagten: \"Wenn du uns einen Zugang in die Stadt zeigst, werden wir dich belohnen.\"" },
      { number: 25, text: "Er zeigte ihnen eine Stelle, wo sie eindringen konnten. Auf diese Weise eroberten die Männer der Josefstämme die Stadt. Sie töteten alle Einwohner mit dem Schwert, doch den Mann und seine ganze Sippe ließen sie gehen." },
      { number: 26, text: "Der zog daraufhin ins Land der Hetiter* und gründete eine Stadt, die er Lus nannte, wie sie heute noch heißt.", footnotes: ["Hetiter. Eine kleinasiatische Völkergruppe, die weder in Sprache noch in Herkunft eine erkennbare Einheit bildeten. Zu dieser Zeit bestanden in Nordsyrien verschiedene hetitische Staaten."] },
      { number: 27, text: "Der Stamm Manasse vertrieb die Einwohner von Bet-Schean*, Taanach, Dor, Jibleam und Megiddo* und den dazugehörenden Ortschaften nicht. Die Kanaaniter setzten alles daran, in dieser Gegend wohnen zu bleiben.", footnotes: ["Bet-Schean, 24 km südlich vom See Gennesaret, war eine bedeutende kanaanitische Stadt und wurde später eine Festung der Philister.", "Megiddo. Bedeutende kanaanitische Stadt am Südwestrand des Jesreel-Tales. Die Festung bewachte einen wichtigen Pass, der durch die Karmel-Bergkette verlief."] },
      { number: 28, text: "Als die Israeliten dann stärker wurden, verpflichteten sie sie zu Zwangsarbeiten, vertrieben sie aber nicht." },
      { number: 29, text: "Auch der Stamm Efraïm vertrieb die Kanaaniter nicht aus der Stadt Geser, denn sie hielten durch und blieben mitten in seinem Gebiet ansässig." },
      { number: 30, text: "Der Stamm Sebulon vertrieb die Einwohner von Kitron und Nahalal* nicht, sodass die Kanaaniter auch unter ihnen wohnen blieben. Später jedoch verpflichtete man sie zu Zwangsarbeiten.", footnotes: ["Nahalal. Vermutlich Orte im Nordwesten der Ebene Jesreel"] },
      { number: 31, text: "Der Stamm Ascher vertrieb die Einwohner von Akko* und Sidon* nicht, und auch nicht die von Mahaleb*, Achsib, Helba*, Afek und Rehob*.", footnotes: ["Akko. Wichtigste Hafenstadt Kanaans am Mittelmeer, später in Ptolemaïs umbenannt.", "Sidon. Wichtigste Hafenstadt Phöniziens, 40 km nördlich von Tyrus. Ihre Einwohner und die der Umgebung werden Sidonier genannt.", "Mahaleb. wahrscheinlich 8 km nordöstlich von Tyrus an der Mittelmeerküste.", "Helba. unbekannte Stadt im Norden Israels.", "Rehob. vielleicht Tell el-Balat, 19 km südöstlich von Tyrus."] },
      { number: 32, text: "Deshalb lebten die Leute von Ascher mitten unter den Kanaanitern, die in der Gegend wohnen blieben, weil man sie nicht vertrieben hatte." },
      { number: 33, text: "Der Stamm Naftali vertrieb die Einwohner von Bet-Schemesch und Bet-Anat* nicht, sondern lebte in seinem Stammesgebiet mit den Kanaanitern zusammen. Sie mussten ihnen jedoch Zwangsarbeiten leisten.", footnotes: ["Bet-Anat. Stadt im oberen Galiläa, 24 km südöstlich von Tyrus."] },
      { number: 34, text: "Als die Männer des Stammes Dan in die Ebene vordringen wollten, wurden sie von den Amoritern* ins Hügelland zurückgedrängt.*", footnotes: ["Amoriter. Bewohner des Landes Kanaan. Amoriter kann sowohl für einen einzelnen Stamm als auch für alle Bewohner Kanaans stehen. Es waren semitische Einwanderer aus der Arabischen Wüste, die um 2000 v.Chr. ins Kulturland eindrangen.", "zurückgedrängt. Das führte später zur Wanderung der Daniten nach Lajisch, siehe Richter 18."] },
      { number: 35, text: "Die Amoriter konnten sich in Har-Heres*, Ajalon und Schaalbim behaupten. Als die beiden Josefstämme später die Oberhand gewannen, verpflichteten sie sie zu Zwangsarbeiten.", footnotes: ["Har-Heres. Sonnenberg, vielleicht mit Bet-Schemesch identisch."] },
      { number: 36, text: "Die Grenze zum Gebiet der Amoriter verläuft von der Skorpionensteige* bis nach Sela* und darüber hinaus.", footnotes: ["Skorpionensteige. Die genaue Lage unbekannt. Vielleicht 32 km südwestlich von der Südspitze des Toten Meeres.", "Sela. Edomitische Festung 37 km südöstlich von der Südspitze des Toten Meeres."] },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Der Engel Jahwes* kam von Gilgal* nach Bochim* herauf und sagte zu den Israeliten: \"Ich habe euch aus Ägypten herausgeführt und euch in das Land gebracht, das ich euren Vätern unter Eid zugesichert hatte. Ich hatte gesagt: 'Niemals werde ich meinen Bund mit euch brechen, nie!", heading: "Der Engel Jahwes", footnotes: ["Engel Jahwes. Hebräisch: Malach Jahwe. Das war kein gewöhnlicher Engel, sondern eine Erscheinung Gottes.", "Gilgal. Wird gewöhnlich mit den Ruinen von Kirbet el-Mafjer identifiziert, 3 km nordöstlich von Jericho. Gilgal klingt an das hebr. Wort für Kreis an.", "Bochim. Ort ungewiss, vielleicht in der Nähe von Beth-El, siehe 1. Mose 35,8."] },
      { number: 2, text: "Aber ihr dürft keinen Bund mit den Bewohnern dieses Landes schließen und müsst ihre Altäre niederreißen.' Doch ihr habt mir nicht gehorcht. Wie konntet ihr das nur tun?" },
      { number: 3, text: "So muss ich euch jetzt sagen: 'Ich werde die Bewohner dieses Landes nicht vor euch vertreiben! Sie werden euch Widerstand leisten und ihre Götter werden zur Falle für euch.\"" },
      { number: 4, text: "Als der Engel Jahwes das gesagt hatte, schrien die Israeliten auf und begannen zu weinen." },
      { number: 5, text: "Darum nannten sie jenen Ort Bochim, die Weinenden. Dort brachten sie Jahwe Opfer." },
      { number: 6, text: "Als Josua damals die Versammlung bei Sichem* aufgelöst hatte, waren die Israeliten in die ihnen zugeteilten Gebiete gezogen, um sie in Besitz zu nehmen.", heading: "Israels Untreue", footnotes: ["Sichem. Strategisch und religiös bedeutende Stadt auf dem Pass (Sichem = Schulter) zwischen den Bergen Ebal im Norden und Garizim im Süden."] },
      { number: 7, text: "Solange Josua lebte, diente das Volk Jahwe, und auch noch solange die Ältesten lebten, die die großen Taten Jahwes für Israel gesehen hatten." },
      { number: 8, text: "Doch dann starb Josua Ben-Nun, der Diener Jahwes, 110 Jahre alt." },
      { number: 9, text: "Sie bestatteten ihn auf seinem Erbbesitz in Timnat-Heres*, im Gebirge Efraïm*, nördlich vom Berg Gaasch*.", footnotes: ["Timnat-Heres. Andre Form für Timnat-Serach, 29 km nordwestlich von Jerusalem.", "Efraïm. Zentrale Bergkette des Westjordanlandes, damals dicht bewaldet.", "Gaasch. Der Berg und die gleichnamige Stadt liegen etwa 30 km südwestlich von Sichem."] },
      { number: 10, text: "Schließlich starb jene ganze ältere Generation und es wuchs eine neue heran, die Jahwe nicht kannte und seine großen Taten für Israel nicht miterlebt hatte." },
      { number: 11, text: "Da fingen die Israeliten an, den Baalen* zu dienen, was Jahwe als sehr böse ansah.", footnotes: ["Baalen. Kanaanitischer Name für den syrischen Gott Hadad, den Gott des Sturmes und der Kriege. Die Mehrzahlform (Hebr. Baalim) verweist auf die zahlreichen Modifikationen der Verehrung Baals, z.B. als Baal-Peor (4Mo 25,3); Baal-Gad (Josua 11,17); Baal-Berit, (Richter 9,4); Baal-Sebub (2. Könige 1,2)."] },
      { number: 12, text: "So verließen sie Jahwe, den Gott ihrer Vorfahren, der sie aus Ägypten herausgeführt hatte, und liefen fremden Göttern nach. Sie warfen sich vor den Göttern ihrer Nachbarvölker nieder und reizten Jahwe auf diese Weise zum Zorn," },
      { number: 13, text: "denn sie verließen ihn dadurch, dass sie Baal und Astarte* verehrten.", footnotes: ["Astarte. In Kanaan Gemahlin Baals, wurde als Fruchtbarkeitsgöttin verehrt."] },
      { number: 14, text: "Da wurde Jahwe zornig über Israel. Er ließ räuberische Beduinen über sie herfallen, die sie ausplünderten. Er lieferte sie der Gewalt ihrer feindlichen Nachbarvölker aus, sodass sie ihnen keinen Widerstand mehr leisten konnten." },
      { number: 15, text: "Sooft sie auch in den Kampf zogen, stellte sich Jahwe gegen sie, wie er es ihnen mit einem Schwur angedroht hatte. So gerieten sie in schwere Bedrängnis." },
      { number: 16, text: "Aber dann ließ Jahwe ihnen immer wieder besondere Führer erstehen, die Richter, die sie aus der Gewalt der plündernden Nachbarstämme befreiten." },
      { number: 17, text: "Aber auch auf ihre Richter hörten sie nicht lange, sondern gaben sich wie Huren immer wieder anderen Göttern hin und warfen sich vor ihnen nieder. Schnell kamen sie vom rechten Weg ab, den ihre Väter gegangen waren und gehorchten den Geboten Jahwes nicht mehr." },
      { number: 18, text: "Trotzdem ließ Jahwe ihnen immer wieder Richter erstehen und stand diesen zur Seite. Er befreite sein Volk aus der Gewalt ihrer Feinde, solange die Richter lebten, denn er hatte Mitleid mit ihnen, wenn sie unter ihren Unterdrückern und Peinigern ächzten." },
      { number: 19, text: "Doch sobald der Richter gestorben war, wurden die Israeliten rückfällig und trieben es noch schlimmer als ihre Vorfahren. In ihrem Trotz hörten sie einfach nicht auf, den anderen Göttern nachzurennen, sie zu verehren und sich vor ihnen niederzuwerfen." },
      { number: 20, text: "Da flammte Jahwes Zorn gegen Israel auf. Er fasste den Beschluss: \"Weil dieses Volk ständig den Bund bricht, den ich mit ihren Vorfahren geschlossen habe, weil es mir einfach nicht gehorchen will," },
      { number: 21, text: "werde auch ich kein einziges Volk mehr vor ihnen vertreiben. Die Völker, die Josua bis zu seinem Tod nicht vertreiben konnte, lasse ich im Land," },
      { number: 22, text: "um die Israeliten auf die Probe zu stellen, ob sie wie ihre Vorfahren auf meinem Weg bleiben oder nicht.\"" },
      { number: 23, text: "Deshalb hatte Jahwe diese Völker im Land bleiben lassen und sie nicht so schnell vertrieben; und deshalb hatte er sie auch Josua nicht in die Hand gegeben." },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Einige Völker ließ Jahwe im Land bleiben, um durch sie die späteren Generationen der Israeliten zu prüfen, die von den Kämpfen um Kanaan nichts mehr wussten.", heading: "3-16: Die Zyklen von Abfall und Umkehr\nFremde Völker unter den Israeliten" },
      { number: 2, text: "Er wollte erkennen, wie sich diese Generationen, die den Krieg nicht mehr kannten, verhalten würden, wenn er sie den Krieg zu führen lehrte." },
      { number: 3, text: "Dazu gebrauchte er die fünf Fürsten der Philister*, alle Kanaaniter und Sidonier* und die Hiwiter*, die im Libanongebirge* zwischen dem Baal-Hermon* und Lebo-Hamat* wohnen.", footnotes: ["Die Philister bewohnten die südlichen Küstenstädte Aschdod, Askalon, Ekron, Gat und Gaza.", "Sidonier. Einwohner der Stadt Sidon, hier wohl für Phönizier, Bewohner des Libanon.", "Hiwitwer. Auch die Einwohner der Städte Gibeon, Kefira, Beerot und Kirjat-Jearim gehörten zu den Hiwitern.", "Libanongebirge. Das weiße Gebirge. 170 km lange und 25 km breite Gebirgskette am Mittelmeer nördlich von Israel, deren höchste Gipfel (über 3000 Meter) fast ganzjährig mit Schnee bedeckt sind. Berühmt sind die bis zu 40 Meter hohen Zedern.", "Baal-Hermon. Drei fast gleich hohe (über 2800 Meter) schneebedeckte Gipfel in Nordgaliläa. Der Hermon wurde von den vorisraelischen Bewohnern als heilig verehrt, deshalb Baal-Hermon.", "Lebo-Hamat. Heute: Labwe, etwa 70 km nördlich vom Hermon."] },
      { number: 4, text: "Durch sie sollten die Israeliten auf die Probe gestellt werden, damit in Erfahrung gebracht würde, ob sie den Geboten Jahwes, die er ihren Vorfahren durch Mose gegeben hatte, gehorchen würden." },
      { number: 5, text: "Die Israeliten wohnten also unter den Kanaanitern, Hetitern, Amoritern, Perisitern, Hiwitern und Jebusitern*.", footnotes: ["Die Jebusiter siedelten auf dem Gebirge Kanaans und in Jebus (Jerusalem)."] },
      { number: 6, text: "Und was taten sie? Sie nahmen sich deren Töchter zu Frauen und verheirateten ihre eigenen Töchter mit deren Söhnen. Und sie dienten deren Göttern." },
      { number: 7, text: "Ja, die Israeliten taten, was Jahwe als böse ansah. Sie vergaßen Jahwe, ihren Gott, und dienten den Baalen und den Ascheren*.", heading: "Der Richter Otniel", footnotes: ["Aschera. Kanaanitische Muttergottheit, oft durch geweihte Pfähle repräsentiert."] },
      { number: 8, text: "Da flammte Jahwes Zorn gegen Israel auf, und er lieferte sie der Gewalt von Kuschan-Rischatajim* aus, einem König im oberen Mesopotamien*. Acht Jahre lang mussten die Israeliten ihm dienen.", footnotes: ["Kuschan-Rischatajim. Das bedeutet: Mohr der doppelten Bosheit", "Mesopotamien. Zweistromland, Landschaft zwischen den Flüssen Euphrat und Tigris, die heute größtenteils zum Irak gehört."] },
      { number: 9, text: "Da schrien sie zu Jahwe um Hilfe und er ließ ihnen einen Retter erstehen: Otniel, der Sohn von Kalebs jüngerem Bruder Kenas." },
      { number: 10, text: "Der Geist Gottes erfüllte ihn, und er wurde Richter in Israel. Dann zog er gegen den Syrerkönig Kuschan-Rischatajim in den Kampf und brachte ihm eine schwere Niederlage bei, weil Jahwe ihn in seine Gewalt gegeben hatte." },
      { number: 11, text: "Daraufhin hatte das Land 40 Jahre lang Ruhe vor seinen Feinden, bis Otniel starb." },
      { number: 12, text: "Aber die Israeliten taten weiterhin Böses vor Jahwe. Da gab Jahwe Eglon, dem König der Moabiter*, Macht über Israel, und zwar weil sie taten, was Jahwe missfiel.", heading: "Der Richter Ehud", footnotes: ["Die Moabiter lebten östlich vom Toten Meer zwischen den Flüssen Arnon und Zered."] },
      { number: 13, text: "Eglon verbündete sich mit den Ammonitern* und Amalekitern*. Er besiegte Israel und besetzte die Palmenstadt*.", footnotes: ["Die Ammoniter waren nordöstliche Nachbarn der Moabiter", "Die Amalekiter waren Todfeinde Israels und lebten als Nomaden im Negev, südlich von Beerscheba.", "Palmenstadt Gemeint ist die sehr fruchtbare Oase Jericho. Die Stadt war ja noch zerstört, siehe Josua 6."] },
      { number: 14, text: "Achtzehn Jahre lang mussten die Israeliten dem Moabiterkönig Eglon Tribut zahlen." },
      { number: 15, text: "Da schrien sie zu Jahwe um Hilfe und er ließ ihnen einen Retter erstehen: Ehud Ben-Gera, einen Linkshänder aus dem Stamm Benjamin. Die Israeliten hatten ihn ausgewählt, den Tribut an König Eglon zu überbringen." },
      { number: 16, text: "Da ließ sich Ehud einen beidseitig geschliffenen Dolch schmieden und gürtete ihn an seine rechte Hüfte unter sein Gewand." },
      { number: 17, text: "So vorbereitet ließ er dem König von Moab den Tribut überbringen. Dieser Eglon war übrigens ein sehr fetter Mann." },
      { number: 18, text: "Nach der Übergabe schickte Ehud die Leute, die den Tribut getragen hatten, nach Hause." },
      { number: 19, text: "Er selbst kehrte bei den Götterbildern*, die in der Nähe von Gilgal standen, wieder um und ging noch einmal zurück. \"Ich habe eine geheime Botschaft an dich, o König!\", sagte er. \"Pst! Ksch!\", machte Eglon. Da gingen alle Diener des Königs hinaus.", footnotes: ["Diese Götterbilder trugen religiöse Inschriften und waren wahrscheinlich von den Moabitern aufgestellt worden, um die Grenze zu Israel zu markieren und gleichzeitig das eigene Land vor fremden Göttern zu schützen."] },
      { number: 20, text: "Nun trat Ehud an den König heran – er saß nämlich in dem kühlen Obergemach, das für ihn allein bestimmt war – und sagte: \"Eine Sache Gottes* habe ich für dich!\" Sogleich erhob sich dieser vom Sitz.", footnotes: ["Sache Gottes. Das kann auch bedeuten: Ein Wort Gottes. Ehud wird aber an sein Schwert gedacht haben."] },
      { number: 21, text: "Da fasste Ehud mit der linken Hand den Dolch, der an seiner rechten Seite hing, und stieß ihn dem König in den Bauch." },
      { number: 22, text: "Die Klinge drang so tief ein, dass das Fett auch den Griff noch umschloss, denn Ehud riss den bis zum Gesäß eingedrungenen Dolch nicht wieder heraus." },
      { number: 23, text: "Danach verriegelte er die Tür des Obergemachs, stieg durchs Fenster und ging über die Vorhalle hinaus." },
      { number: 24, text: "Als er gegangen war, kamen Eglons Diener und sahen, dass die Türflügel des Obergemachs verriegelt waren. \"Er verrichtet wohl gerade seine Notdurft in der kühlen Kammer\", meinten sie." },
      { number: 25, text: "Sie warteten aber vergeblich, denn er öffnete die Tür nicht. Schließlich holten sie einen Schlüssel und schlossen auf. Da lag ihr Herr tot auf dem Boden." },
      { number: 26, text: "Während die Diener gewartet hatten, war Ehud entkommen. Er war schon an den Götterbildern vorbei und konnte sich nach Seïra* in Sicherheit bringen.", footnotes: ["Seïra. Unbekannter Ort im Gebirge Efraïm."] },
      { number: 27, text: "Sobald er dort angekommen war, blies er überall auf dem Gebirge Efraïm das Signalhorn*. Da zogen die Männer Israels hinter ihm her vom Gebirge hinab.", footnotes: ["Das Signalhorn (Hebräisch: Schofar) war aus den gewundenen Hörnern des männlichen Fettschwanzschafes hergestellt und brachte einen dumpfen, durchdringenden Ton hervor."] },
      { number: 28, text: "\"Folgt mir!\", rief er, \"Jahwe hat eure Feinde, die Moabiter in eure Hand gegeben.\" So folgten sie ihm bis ins Jordantal hinunter und besetzten die Flussübergänge, sodass die Moabiter nicht entkommen konnten." },
      { number: 29, text: "Damals erschlugen sie an die 10.000 Moabiter, alles starke und kriegstüchtige Männer. Keiner entkam." },
      { number: 30, text: "An diesem Tag musste sich Moab der Gewalt Israels unterwerfen. Daraufhin hatte das Land 80 Jahre lang Ruhe vor seinen Feinden." },
      { number: 31, text: "Nach Ehud trat Schamgar Ben-Anat auf. Er erschlug 600 Philister mit einem Stab, der eine scharfe Spitze hatte, und normalerweise zum Antreiben von Rindern verwendet wurde. Auch er rettete die Israeliten vor ihren Feinden.", heading: "Schamgar" },
    ] },
    { number: 4, verses: [
      { number: 1, text: "Nach dem Tod Ehuds taten die Israeliten weiter, was Jahwe als böse ansah.", heading: "Die Richterin Debora" },
      { number: 2, text: "Da lieferte er sie dem Kanaaniterkönig Jabin aus, der in Hazor* regierte. Dessen Heerführer Sisera hatte sein Hauptquartier in Haroschet-Gojim*.", footnotes: ["Hazor. Wichtigste kanaanitische Festung im Norden, 14 km nördlich vom See von Galiläa.", "Haroschet-Gojim. Vielleicht Tell el-Amar, 16 km nordwestlich von Megiddo."] },
      { number: 3, text: "Jabin besaß nämlich 900 eiserne Streitwagen und hatte die Israeliten 20 Jahre lang grausam unterdrückt. Da schrien sie zu Jahwe um Hilfe." },
      { number: 4, text: "Damals war Debora Richterin in Israel. Sie war die Frau Lappidots und eine Prophetin." },
      { number: 5, text: "Ihren Sitz hatte sie unter der Debora-Palme zwischen Rama* und Bet-El im Gebirge Efraïm. Die Israeliten kamen zu ihr hinauf, um sich von ihr Recht sprechen zu lassen.", footnotes: ["Rama. 9 km nördlich von Jerusalem im Stammesgebiet von Benjamin."] },
      { number: 6, text: "Eines Tages ließ sie Barak Ben-Abinoam aus Kedesch in Naftali* zu sich holen und sagte zu ihm: \"Jahwe, der Gott Israels, befiehlt: 'Nimm 10.000 Mann aus den Stämmen Naftali und Sebulon und zieh mit ihnen auf den Berg Tabor*!", footnotes: ["Kedesch in Naftali. Gewöhnlich mit einem Ort 8 km westlich des Hulesees identifiziert.", "Tabor. Kegelförmiger Berg, 8 km östlich von dem späteren Nazaret gelegen, 588 Meter über N.N."] },
      { number: 7, text: "Ich werde Sisera, den Heerführer Jabins, mit seinen Wagen und seiner Streitmacht an den Bach Kischon* locken und ihn dort in deine Hand geben.'\"", footnotes: ["Kischon. Kleiner Fluss im westlichen Teil der Jesreel-Ebene."] },
      { number: 8, text: "\"Wenn du mitgehst\", erwiderte Barak, \"will ich gehen, sonst gehe ich nicht!\"" },
      { number: 9, text: "\"Gut, ich gehe mit\", erwiderte Debora, \"doch der Ruhm für den Sieg wird dann nicht dir gehören, denn Jahwe wird Sisera in die Hände einer Frau fallen lassen.\" Debora machte sich fertig und ging mit Barak nach Kedesch." },
      { number: 10, text: "Dort rief Barak die Männer von Sebulon und Naftali zusammen. 10.000 Mann folgten seinem Ruf und zogen mit ihm auf den Tabor. Auch Debora kam mit." },
      { number: 11, text: "Einige Zeit vorher hatte sich der Keniter Heber von seinem Stamm getrennt, den Nachkommen von Moses Schwager Hobab. Er hatte sein Zelt bei der Terebinthe* von Zaanajim aufgeschlagen, das in der Nähe von Kedesch liegt.", footnotes: ["Terebinthe. Belaubter Baum mit breitem Wipfel, der nicht mehr als 7 m hoch wird und als Schattenspender geschätzt ist."] },
      { number: 12, text: "Nun berichtete man Sisera, dass Barak Ben-Abinoam eine Armee auf den Berg Tabor geführt hatte." },
      { number: 13, text: "Da beorderte er seine 900 Streitwagen und seine ganze Heeresmacht, die sich in Haroschet-Gojim befand, an den Bach Kischon." },
      { number: 14, text: "Als sie eingetroffen waren, sagte Debora zu Barak: \"Los, greif an! Heute hat Jahwe dir den Sieg über Sisera in die Hand gegeben. Er selbst zieht vor dir her.\" Da stürmte Barak vom Berg Tabor hinunter, und die Zehntausend folgten ihm." },
      { number: 15, text: "Als sie mit gezücktem Schwert auf ihre Feinde zukamen, ließ Jahwe das ganze feindliche Heer samt ihrem Anführer und den Streitwagen in Panik geraten. Sisera selbst sprang von seinem Wagen und floh zu Fuß." },
      { number: 16, text: "Barak verfolgte die Wagen und das Heer bis nach Haroschet-Gojim. So wurde die ganze Armee Siseras vernichtet. Kein einziger entkam." },
      { number: 17, text: "Sisera war auf seiner Flucht zu Fuß inzwischen bis zum Zelt Jaëls gekommen, das war die Frau des Keniters Heber. Die Sippe Hebers unterhielt freundschaftliche Beziehungen zu Jabin, dem König von Hazor." },
      { number: 18, text: "Jaël trat aus dem Zelt, ging Sisera entgegen und sagte: \"Kehr ruhig bei mir ein, mein Herr! Komm herein! Hab keine Angst!\"* So ging er mit ihr ins Zelt, und sie deckte ihn mit einem Vorhang zu.", footnotes: ["keine Angst. Im Orient durfte kein anderer Mann das Zelt einer Frau betreten außer ihrem Vater und ihrem Ehemann. So bot sie ihm ein ideales Versteck an."] },
      { number: 19, text: "\"Gib mir ein wenig Wasser!\", sagte er zu ihr. \"Ich habe Durst.\" Da holte sie einen Schlauch mit Milch und gab ihm zu trinken. Dann deckte sie ihn wieder zu." },
      { number: 20, text: "\"Stell dich doch an den Zelteingang!\", sagte er noch zu ihr. \"Wenn jemand kommt und dich fragt, ob jemand hier ist, dann sag: 'Nein!'\"" },
      { number: 21, text: "Doch Jaël, die Frau Hebers, holte einen Zeltpflock, nahm einen Hammer in die Hand und ging leise zu Sisera hin, der vor Erschöpfung in tiefen Schlaf gefallen war. Sie trieb ihm den Zeltpflock so durch die Schläfen, dass er noch in die Erde drang. Auf diese Weise starb Sisera." },
      { number: 22, text: "Da kam auch schon Barak, der Sisera verfolgt hatte. Jaël trat aus dem Zelt, ging ihm entgegen und sagte: \"Komm mit, ich zeige dir den Mann, den du suchst!\" Barak ging mit ihr ins Zelt und fand Sisera mit einem Zeltpflock im Kopf tot auf der Erde liegen." },
      { number: 23, text: "So zwang Gott an jenem Tag den Kanaaniterkönig Jabin in die Knie." },
      { number: 24, text: "Und in der Folgezeit lag die Faust Israels immer härter auf seinem Stamm, bis er ganz vernichtet war." },
    ] },
    { number: 5, verses: [
      { number: 1, text: "An jenem Tag sangen Debora und Barak Ben-Abinoam das folgende Lied:", heading: "Deboras Lied" },
      { number: 2, text: "Dass Führer Israel führten / und das Volk freiwillig kämpfte, / preist Jahwe dafür!" },
      { number: 3, text: "Ihr Könige, hört her! / Ihr Fürsten, merkt auf! / Ich will singen zur Ehre Jahwes, / die Saiten klingen lassen für Israels Gott." },
      { number: 4, text: "Als du auszogst, Jahwe, von Seïr*, / und durch Edoms* Steppen kamst, / da bebte die Erde, / da brach der Himmel, / aus den Wolken ergoss sich die Flut.", footnotes: ["Seïr. Gebirge südöstlich vom Toten Meer.", "Edom. Land östlich der Araba im Süden des Toten Meeres, bewohnt von den Nachkommen Esaus."] },
      { number: 5, text: "Die Berge wankten vor Jahwe, / als Gott seinem Volk am Sinai* erschien.", footnotes: ["Sinai. Berg der Gesetzgebung in der Wüste Sinai, siehe 2. Mose 19."] },
      { number: 6, text: "Zur Zeit von Schamgar Ben-Anat* / und jetzt in den Tagen von Jaël, / da waren alle Wege menschenleer. / Wer reisen wollte, musste auf versteckten Pfaden gehen.", footnotes: ["Schamgar Ben-Anat. Siehe Kapitel 3,31."] },
      { number: 7, text: "Felder und Dörfer lagen verwaist – bis ich mich erhob, / bis aufstand eine Mutter in Israel." },
      { number: 8, text: "Mein Volk hatte sich neue Götter erwählt, / und dann brach der Feind durch die Tore herein. / Hat einer wohl Schild und Lanze gesehen / bei 40.000 Männern in Israel?" },
      { number: 9, text: "Mein Herz gehört Israels Führern / und den Freiwilligen im Volk. / Preist Jahwe!" },
      { number: 10, text: "Singt, die ihr auf weißen Eseln reitet / und auf kostbaren Decken sitzt! / Singt, die ihr durch die Straßen zieht!" },
      { number: 11, text: "Hört, wie sie jubeln zwischen den Tränken! / Dort besingt man die rettenden Taten Jahwes. / Sie erzählen, wie er seinem Volk half.Dann zog sein Volk zu den Toren hinab:" },
      { number: 12, text: "Auf, auf, Debora! Wach auf und singe ein Lied! / Auf, Barak, Abinoams Sohn! / Führe deine Gefangenen vor!" },
      { number: 13, text: "Es kamen alle, die noch übrig waren / und schlossen sich den Führern Israels an. Gerüstet kam das Volk Jahwes zu mir." },
      { number: 14, text: "Aus Efraïm, das stark und heiß wie Amalek ist, zogen die Scharen ins Tal, / auch Benjamins Männer folgten der Spur. / Von Machir* stiegen die Führer herab, / von Sebulon die mit dem Befehlshaberstab.", footnotes: ["Machir. Teil des Stammes Manasse im Ostjordanland."] },
      { number: 15, text: "Auch Issachars Fürsten kamen zu Debora, / und Barak mit seinem ganzen Gefolge. / So stürmten sie hinunter ins Tal. – Doch an Rubens Bächen überlegte man lang." },
      { number: 16, text: "Warum bist du bei deinen Herden geblieben / und hörtest den Flöten der Hirten zu? / Ja, an Rubens Bächen überlegte man lang." },
      { number: 17, text: "Gilead* blieb hinter dem Jordan stehen. / Und warum hielt sich Dan bei den Schiffen auf? / Die von Ascher saßen am Strand, / blieben faul in ihren Buchten am Meer.", footnotes: ["Gilead. Landschaft östlich des Jordan, Wohnsitz der Stämme Ruben, Gad und halb Manasse."] },
      { number: 18, text: "Doch Sebulon ist ein Volk, / das sein Leben aufs Spiel gesetzt hat. / Auch Naftali zog aufs Schlachtfeld hinaus / und hatte keine Furcht vor dem Tod." },
      { number: 19, text: "Könige kamen und kämpften, / Kanaans Könige führten Krieg – bei Taanach und bei Megiddos Bach – doch silberne Beute holten sie nicht." },
      { number: 20, text: "Von himmlischen Bahnen her kämpften die Sterne, / gegen Sisera stellten sie ihre Macht." },
      { number: 21, text: "Der Bach Kischon schwemmte sie fort, / der uralte Bach riss die Feinde hinweg.* / Vorwärts, meine Seele, sei stark!", footnotes: ["Bach riss ... hinweg. Gott hatte einen Platzregen kommen lassen, der das Wadi Kischon zu einem reißenden Bach machte."] },
      { number: 22, text: "Die Pferde donnerten im Galopp vorbei, / unter ihren Hufen dröhnte die Erde." },
      { number: 23, text: "\"Ihr sollt Meros* verfluchen\", spricht der Engel Jahwes. / Verflucht die Bewohner der Stadt! / Denn sie eilten nicht zur Hilfe herbei, / zu Jahwe unter den Helden.", footnotes: ["Meros. Ort im Stammesgebiet von Naftali viell. das heutige Chirbet Marus, etwa 10 km südl. von Kedesch."] },
      { number: 24, text: "Preist Jaël, die Frau des Keniters Heber, / rühmt sie mehr als jede andere Frau! / Gesegnet sei sie unter den Frauen im Zelt!" },
      { number: 25, text: "Als Sisera um Wasser bat, reichte sie Milch, / in kostbarer Schale gab sie ihm Rahm." },
      { number: 26, text: "Dann griff sie mit der Linken den Pflock. / Den schweren Hammer in rechter Hand schlug sie zu, / durchbohrte die Schläfe / und zerschmetterte Siseras Kopf." },
      { number: 27, text: "Er krümmte sich zu ihren Füßen, / erschlagen lag er da. / Er krümmte sich zu ihren Füßen und war tot." },
      { number: 28, text: "Seine Mutter späht zum Fenster hinaus, / blickt durch das Gitter von Sorge erfüllt. / Warum sehe ich seinen Wagen noch nicht? / Wo ist der Hufschlag seines Gespanns?" },
      { number: 29, text: "Die Klügste ihrer Edelfrauen antwortet ihr, / und sie selbst wiederholt ihren Trost:" },
      { number: 30, text: "\"Gewiss haben sie die Beute verteilt, / ein oder zwei Mädchen pro Mann, / für Sisera den teuren Stoff. Ja, bunte Kleider bringen sie mit, / zwei kostbare Tücher für deinen Hals.\"" },
      { number: 31, text: "So möge es all deinen Feinden ergehen, Jahwe! / Doch die ihn lieben, sollen sein wie die Sonne, / die aufgeht in ganzer Pracht!Daraufhin hatte das Land 40 Jahre lang Ruhe vor seinen Feinden." },
    ] },
    { number: 6, verses: [
      { number: 1, text: "Von neuem taten die Israeliten, was Jahwe als böse ansah. Da lieferte er sie den Midianitern* aus – sieben Jahre lang.", heading: "Gideons Berufung", footnotes: ["Midianiter. Nomadenvolk, das in der Araba (Jordantal) und in Transjordanien umherzog."] },
      { number: 2, text: "Die Midianiter setzten ihnen derartig zu, dass sich die Israeliten Felslöcher zurecht machten, Höhlen und unzugängliche Plätze in den Bergen." },
      { number: 3, text: "Denn immer, wenn sie ihre Felder bestellt hatten, kamen die Midianiter mit den Amalekitern und Nomaden aus dem Osten" },
      { number: 4, text: "und machten sich im Land breit. Sie vernichteten die Ernte bis zu der Stelle, wo es nach Gaza geht, und ließen nichts Essbares zurück. Sie raubten Schafe, Rinder und Esel." },
      { number: 5, text: "Mit ihren Herden und Zelten kamen sie wie Heuschrecken über das Land und verwüsteten alles. Sie und ihre Kamele waren nicht zu zählen." },
      { number: 6, text: "Die Israeliten wurden bettelarm durch sie. Da schrien sie zu Jahwe um Hilfe." },
      { number: 7, text: "Als sie das taten," },
      { number: 8, text: "schickte Jahwe ihnen einen Propheten, der Folgendes sagte: \"So spricht Jahwe, Israels Gott: Ich habe euch aus dem Sklavenhaus Ägypten herausgeholt." },
      { number: 9, text: "Ich habe euch aus seiner Gewalt befreit. Und alle eure Peiniger vertrieb ich vor euch, und ich gab euch ihr Land." },
      { number: 10, text: "Ich sagte: Ich bin Jahwe, euer Gott! Ihr sollt die Götter der Amoriter nicht verehren, in deren Land ihr jetzt wohnt! Aber ihr habt nicht auf mich gehört!\"" },
      { number: 11, text: "Da kam der Engel Jahwes und setzte sich unter die Terebinthe bei Ofra*, die Joasch gehörte, einem Mann aus der Abiëser-Sippe. Dessen Sohn Gideon war gerade dabei, Weizen in einer Kelter* zu dreschen, um ihn vor den Midianitern in Sicherheit zu bringen.", footnotes: ["Ofra. Ort im Stammesgebiet von Manasse, 8 km südlich von Megiddo.", "Kelter. In den Fels gehauene Grube, die zum Weinpressen diente."] },
      { number: 12, text: "Der Engel Jahwes zeigte sich ihm und sprach ihn an: \"Jahwe ist mit dir, du tapferer Held!\"" },
      { number: 13, text: "\"Ach mein Herr\", erwiderte Gideon, \"wenn Jahwe wirklich mit uns ist, warum hat uns dann das alles getroffen? Wo sind denn alle seine Wunder, von denen uns unsere Väter erzählt haben? Sie sagten, Jahwe habe uns aus Ägypten hierher geführt. Aber jetzt hat er uns im Stich gelassen und den Midianitern ausgeliefert.\"" },
      { number: 14, text: "Da wandte sich Jahwe ihm zu und sagte: \"Du sollst gehen und mit der Kraft, die du hast, Israel aus der Faust der Midianiter befreien! Ja, ich sende dich!\"" },
      { number: 15, text: "\"Aber mein Herr\", rief Gideon, \"womit soll ich Israel denn befreien? Meine Heereseinheit ist die kleinste im ganzen Stamm Manasse und ich bin der Jüngste in unserer Familie.\"" },
      { number: 16, text: "\"Ich werde mit dir sein\", sagte Jahwe, \"und du wirst die Midianiter schlagen wie einen einzelnen Mann.\"" },
      { number: 17, text: "\"Wenn du mir so viel Gunst erweisen willst, dann gib mir doch ein Zeichen, dass du wirklich mit mir redest." },
      { number: 18, text: "Geh bitte nicht weg, bis ich zurückkomme; ich will eine Gabe bringen und vor dir niederlegen.\" – \"Ich warte, bis du wiederkommst\", versicherte er." },
      { number: 19, text: "Da ging Gideon nach Hause, bereitete ein Ziegenböckchen zu und backte ungesäuertes Brot aus einem Backtrog* voll Mehl. Dann legte er das Fleisch in einen Korb, goss die Brühe in einen Topf und brachte alles unter die Terebinthe, um es dem Engel Jahwes anzubieten.", footnotes: ["Backtrog. Wörtlich: ein Efa, Hohlmaß von etwa 22 Liter."] },
      { number: 20, text: "Doch dieser sagte: \"Nimm das Fleisch und die Brote und leg sie da auf den Felsen, aber die Brühe schütte weg!\" Gideon tat es." },
      { number: 21, text: "Dann berührte der Engel Jahwes mit der Spitze seines Stabes das Fleisch und die Brote. Da schlug Feuer aus dem Felsen und verzehrte alles. Gleichzeitig verschwand der Engel Jahwes." },
      { number: 22, text: "Als nun Gideon sah, dass es wirklich der Engel Jahwes gewesen war, rief er: \"Weh mir, Herr, mein Gott! Ich habe dem Engel Jahwes in die Augen gesehen!\"" },
      { number: 23, text: "Doch Jahwe sagte zu ihm: \"Schalom*, beruhige dich! Hab keine Angst! Du musst nicht sterben.\"", footnotes: ["Schalom. Frieden, Wohlergehen, Wohlbefinden, Unversehrtheit; auch als Grußformel gebraucht."] },
      { number: 24, text: "Da baute Gideon an derselben Stelle einen Altar und nannte ihn \"Jahwe-Schalom\". Der Altar steht heute noch in Ofra, der Stadt der Abiëser-Sippe." },
      { number: 25, text: "In derselben Nacht sagte Jahwe zu Gideon: \"Nimm den siebenjährigen Stier deines Vaters, das zweitbeste Tier aus seiner Herde! Reiß den Altar Baals nieder, der auf dem Grundstück deines Vaters steht, und haue den Aschera-Pfahl* daneben um.", heading: "Zerstörung des Baal-Altars", footnotes: ["Aschera-Pfahl. Die Aschera war eine Fruchtbarkeitsgöttin, die in handlichen Figuren, geweihten Bäumen oder Pfählen verehrt wurde."] },
      { number: 26, text: "Dann baue dort oben, auf der höchsten Stelle eurer Bergfestung, einen Altar für Jahwe, indem du Steine aufeinander schichtest, und opfere mir darauf den Stier als Brandopfer*. Als Brennholz sollst du den umgehauenen Aschera-Pfahl benutzen.\"", footnotes: ["Brandopfer. Bei dieser Opferart wurde das Tier vollständig auf dem Altar verbrannt."] },
      { number: 27, text: "Da nahm Gideon zehn seiner Männer mit und machte das, was Jahwe ihm gesagt hatte. Er tat es jedoch im Schutz der Nacht, weil er sich vor seinen Angehörigen und den Männern der Stadt fürchtete." },
      { number: 28, text: "Am nächsten Morgen entdeckten diese, dass der Altar Baals umgerissen und der Aschera-Pfahl daneben umgehauen war. Sie stellten auch fest, dass der zweitbeste Stier auf dem neuen Altar geopfert worden war." },
      { number: 29, text: "\"Wer hat das getan?\", fragten sie sich. Sie fingen an, nachzuforschen und erfuhren: \"Es war Gideon Ben-Joasch.\"" },
      { number: 30, text: "Da verlangten die Männer der Stadt von Joasch: \"Gib deinen Sohn heraus! Er muss sterben, weil er den Altar des Baal niedergerissen und den Aschera-Pfahl umgehauen hat.\"" },
      { number: 31, text: "Doch Joasch widersprach den Versammelten: \"Wollt ihr etwa den Baal verteidigen? Wollt ihr ihn vielleicht retten? Wenn ihr das tut, wird keiner von euch bis morgen früh am Leben bleiben! Wenn er wirklich ein Gott ist, soll er sich doch selber für das Einreißen seines Altars rächen.\"" },
      { number: 32, text: "Von dem Tag an nannte man Gideon Jerub-Baal – das heißt: Baal setze sich mit ihm auseinander –, weil er den Baals-Altar niedergerissen hatte." },
      { number: 33, text: "Und wieder taten sich die Midianiter, die Amalekiter und die Nomaden aus dem Osten zusammen. Sie überschritten den Jordan und machten sich in der Ebene Jesreel* breit.", heading: "Bestätigungszeichen", footnotes: ["Jesreel. Sehr fruchtbare Ebene, 40 km nördlich von Samaria, Schauplatz vieler Schlachten."] },
      { number: 34, text: "Da wurde Gideon vom Geist Jahwes erfüllt. Er blies das Horn, und die Männer der Abiëser-Sippe folgten seinem Ruf." },
      { number: 35, text: "Dann schickte er Boten in das ganze Stammesgebiet von Manasse und zu den Stämmen Ascher, Sebulon und Naftali. Von überall her ließen die Männer sich rufen und schlossen sich Gideons Truppe an." },
      { number: 36, text: "Inzwischen betete Gideon zu Gott: \"Ich weiß, dass du versprochen hast, Israel durch mich zu befreien, aber gib mir doch bitte noch eine Bestätigung dafür!" },
      { number: 37, text: "Schau, ich lege jetzt frisch geschorene Wolle auf den Dreschplatz. Wenn die Schafwolle morgen früh nass sein wird und ringsherum alles trocken, dann werde ich sicher sein, dass du Israel durch mich retten willst, wie du es gesagt hast.\"" },
      { number: 38, text: "Als Gideon früh am nächsten Morgen aufstand und den Tau aus der Wolle ausdrückte, füllte das Wasser eine ganze Schale." },
      { number: 39, text: "Doch Gideon betete noch einmal zu Gott: \"Sei mir nicht böse, wenn ich dich noch ein einziges Mal um ein Zeichen bitte. Lass es mich doch noch einmal mit der Wolle versuchen und lass sie morgen früh trocken sein, aber ringsum alles nass vom Tau!\"" },
      { number: 40, text: "Gott erfüllte ihm auch diese Bitte in der kommenden Nacht: Die Wolle blieb trocken und der ganze Boden war nass vom Tau." },
    ] },
    { number: 7, verses: [
      { number: 1, text: "Am frühen Morgen brach Jerub-Baal, also Gideon, mit seinem ganzen Heer auf. Ihr Lager errichteten sie bei der Harod-Quelle*. Das Lager der Midianiter befand sich nördlich davon, in der Ebene am Hügel More*.", heading: "Die richtigen Kämpfer", footnotes: ["Harod-Quelle. Wahrscheinlich En Harod am Fuß des Berges Gilboa. Der Bach windet sich von dort aus Richtung Jordan.", "More. Der Hügel ragt wie ein Wächter auf und bewacht den Eingang zum Tal Jesreel. Er ist etwa 5 km von der Harod-Quelle entfernt."] },
      { number: 2, text: "Aber Jahwe sagte zu Gideon: \"Dein Heer ist zu groß! So kann ich euch den Sieg über die Midianiter nicht geben. Die Israeliten sollen sich nicht vor mir rühmen können und sagen: 'Wir haben uns aus eigener Kraft befreit!'" },
      { number: 3, text: "Lass daher im ganzen Lager ausrufen, dass alle, die Angst haben, nach Hause gehen* sollen.\" Da machten 22.000 Mann kehrt, und nur 10.000 blieben zurück.", footnotes: ["nach Hause gehen. Wörtlich: sich vom Gebirge Gilead abwenden. Dieses Gebirge liegt allerdings auf der Ostjordanseite, aber es war wohl vom Lager aus zu sehen."] },
      { number: 4, text: "Doch Jahwe sagte zu Gideon: \"Dein Heer ist immer noch zu groß. Führe die Männer ans Wasser hinunter, dort will ich sie für dich mustern. Ich werde dir sagen, wer mit dir gehen soll und wer nicht.\"" },
      { number: 5, text: "Gideon führte die Leute ans Wasser. Dann sagte Jahwe: \"Alle, die das Wasser mit der Zunge aufschlürfen wie ein Hund, stell auf die eine Seite, und alle, die sich zum Trinken hinknien, auf die andere.\"" },
      { number: 6, text: "Dreihundert Männer schlürften das Wasser aus der hohlen Hand*, die anderen knieten sich zum Trinken hin.", footnotes: ["hohlen Hand. Sie hatten das Wasser offenbar stehend geschöpft."] },
      { number: 7, text: "Da sagte Jahwe zu Gideon: \"Durch die 300 Mann, die das Wasser geschlürft haben, will ich Israel retten und die Midianiter in deine Hand geben. Die anderen sollen nach Hause gehen.\"" },
      { number: 8, text: "Gideon entließ die Israeliten und behielt nur die 300 Männer bei sich. Diese übernahmen den Proviant und die Hörner* von den anderen. Das geschah oberhalb der Ebene, in der sich das Lager der Midianiter befand.", footnotes: ["Hörner. Hebräisch: Schofarot. Der Schofar wurde aus den gewundenen Hörnern des männlichen Fettschwanzschafes hergestellt und brachte einen dumpfen, durchdringenden Ton hervor."] },
      { number: 9, text: "In der Nacht sagte Jahwe zu Gideon: \"Greif das Lager dort unten an! Ich gebe es in deine Hand.", heading: "Noch eine Bestätigung" },
      { number: 10, text: "Wenn du aber Angst hast, schleich dich vorher mit deinem Burschen Pura hinunter" },
      { number: 11, text: "und hör dir an, was sie miteinander reden. Das wird dir Mut machen, sie anzugreifen.\" Da schlich sich Gideon mit seinem Burschen bis an die bewaffneten Vorposten heran." },
      { number: 12, text: "Die Midianiter, die Amalekiter und die Nomaden aus dem Osten waren wie Heuschrecken in die Talebene eingefallen. Ihre Kamele waren zahllos wie der Sand am Meeresstrand." },
      { number: 13, text: "Als Gideon sich angeschlichen hatte, erzählte gerade einer seinem Kameraden einen Traum. \"Hör zu\", sagte er, \"ich habe geträumt, dass ein Laib Gerstenbrot sich in unser Lager herunterwälzte und das Zelt umriss, sodass alles durcheinander flog und zu Boden stürzte.\"" },
      { number: 14, text: "Sein Kamerad erwiderte: \"Das kann nur eins bedeuten: Das Schwert von Gideon Ben-Joasch aus Israel. Gott hat die Midianiter und das ganze Lager in seine Hand gegeben.\"" },
      { number: 15, text: "Als Gideon den Traum und seine Deutung gehört hatte, warf er sich nieder und betete Gott an. Dann kehrte er ins Lager Israels zurück und rief: \"Steht auf! Jahwe hat das Lager der Midianiter in eure Hand gegeben.\"" },
      { number: 16, text: "Gideon teilte die 300 Mann in drei Gruppen auf. Jeder Kämpfer bekam ein Horn, eine Fackel und einen leeren Krug, um die brennende Fackel zu verbergen.", heading: "Gideons Sieg" },
      { number: 17, text: "\"Achtet genau auf das, was ich tue, wenn ich mit meinen Leuten an den Rand des feindlichen Lagers komme\", sagte Gideon, \"und macht es uns genau nach." },
      { number: 18, text: "Und wenn ich dann ins Horn stoße, sollt auch ihr rings um das Lager das Horn blasen und rufen: 'Für Jahwe und Gideon!'\"" },
      { number: 19, text: "Zu Beginn der mittleren Nachtwache* erreichte Gideon mit seinen 100 Mann das Lager. Die Posten waren gerade abgelöst worden. Da stießen sie in die Hörner und zerschlugen die Krüge, die sie mitgebracht hatten.", footnotes: ["Nachtwache. Im Altertum teilten viele Völker die Nacht in drei Wachen ein: Sonnenuntergang bis 22 Uhr, 22 Uhr bis 2 Uhr, 2 Uhr bis 6 Uhr. Es war also kurz nach 22 Uhr, das feindliche Heer hatte sich schlafen gelegt."] },
      { number: 20, text: "Alle drei Gruppen bliesen die Hörner und zerschlugen ihre Krüge. Dann packten sie mit der linken Hand die Fackel. Mit der rechten hielten sie die Hörner zum Blasen an den Mund und zwischendurch riefen sie: \"Schwert Jahwes und Gideons!\"" },
      { number: 21, text: "Dabei blieben sie um das Lager herum stehen. Da rannte das ganze feindliche Lager durcheinander. Alle schrien laut und flohen." },
      { number: 22, text: "Denn als die 300 Mann in die Hörner stießen, ließ Jahwe eine Panik im ganzen Lager entstehen. Jeder ging mit seinem Schwert auf den anderen los. So floh das ganze Heer auf Bet-Schitta* zu, um nach Zereda* zu entkommen und den Jordanübergang von Abel-Mehola* bei Tabbat* zu erreichen.", footnotes: ["Ben-Schitta. Heute: Schatta, westlich von Bet Schean.", "Zereda. Wahrscheinlich Zaretan auf der Ostseite des Jordan.", "Abel-Mehola. Heimatort des Propheten Elisa.", "Tabbat. Der Ort auf der Anhöhe Ras Abu Tabat liegt am Rand eines Weges, der von einer Jordanfurt nach Osten führt."] },
      { number: 23, text: "Nun wurden Israels Mannschaften aus den Stämmen Naftali, Ascher und ganz Manasse aufgeboten, um die Midianiter zu verfolgen." },
      { number: 24, text: "Gideon hatte auch Boten im Bergland von Efraïm umhergeschickt und sagen lassen: \"Kommt herab und stellt euch den Midianitern entgegen! Besetzt die Wasserstellen bis nach Bet-Bara* und die Übergänge des Jordan!\" Die Männer von Efraïm waren der Aufforderung gefolgt und hatten die Wasserstellen und Jordanfurten abgeriegelt.", footnotes: ["Bet-Bara. Vermutlich gegenüber der Einmündung des Jabbok in den Jordan."] },
      { number: 25, text: "Dabei konnten sie zwei midianitische Fürsten, Oreb und Seeb*, gefangen nehmen. Oreb töteten sie am Rabenfelsen und Seeb an der Wolfskelter. Dann verfolgten sie die Midianiter. Die abgeschlagenen Köpfe der beiden Fürsten brachten sie zu Gideon auf die andere Jordanseite.", footnotes: ["Oreb und Seeb. Hebräisch: \"Rabe\" und \"Wolf\"."] },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Doch dabei machten die Männer des Stammes Efraïm Gideon heftige Vorwürfe: \"Was hast du uns da angetan? Warum hast du uns nicht rufen lassen, als du zum Kampf gegen die Midianiter aufgebrochen bist?\"", heading: "Ein Stamm fühlt sich übergangen" },
      { number: 2, text: "Doch Gideon antwortete: \"Was habe ich denn schon geleistet im Vergleich zu euch? Ist die Nachlese Efraïms nicht besser als die ganze Weinlese Abiësers?" },
      { number: 3, text: "Euch hat Gott doch die Fürsten der Midianiter, Oreb und Seeb in die Hand gegeben! Das stellt alles in den Schatten, was ich getan habe.\" Mit diesen Worten besänftigte er sie, und sie gaben sich zufrieden." },
      { number: 4, text: "Als Gideon mit seinen 300 Männern erschöpft von der Verfolgung den Jordan überquert hatte,", heading: "Der Feldzug im Ostjordanland" },
      { number: 5, text: "bat er die Bewohner von Sukkot*: \"Gebt meinen Leuten doch ein paar Brotlaibe. Sie sind ganz erschöpft. Wir verfolgen die Midianiterkönige Sebach und Zalmunna.\"", footnotes: ["Sukkot. Ort im Ostjordanland zwischen Jabbok und Jordan."] },
      { number: 6, text: "Doch die Stadtobersten erwiderten: \"Hast du Sebach und Zalmunna denn schon in der Hand? Warum sollen wir deiner Truppe Brot geben?\"" },
      { number: 7, text: "Da sagte Gideon: \"Das werdet ihr mir büßen! Wenn Jahwe die beiden Könige in meine Hand gegeben hat, werde ich euch mit Wüstendorn und Stechdistel zerdreschen.\"" },
      { number: 8, text: "Dann zog er nach Pnuël* weiter und bat auch dort um Brot. Doch er bekam die gleiche Antwort wie in Sukkot.", footnotes: ["Pnuel. Amoritische Festung an einer Furt des Jabbok, 8 km östlich von Sukkot."] },
      { number: 9, text: "\"Wenn ich heil zurückkomme, reiße ich eure Burg nieder\", drohte Gideon." },
      { number: 10, text: "Sebach und Zalmunna hatten mit ihren Truppen – etwa 15.000 Mann – in Karkor* Halt gemacht. Das war alles, was von dem ganzen Heerlager der östlichen Nomaden übrig geblieben war. 120.000 Kämpfer waren gefallen.", footnotes: ["Karkor. Ortslage unbekannt."] },
      { number: 11, text: "Gideon folgte ihnen auf der Beduinenstraße, die östlich von Nobach und Jogboha* verläuft, und griff das feindliche Heer, das sich in Sicherheit wähnte, völlig unerwartet an.", footnotes: ["Jogboha. 24 km südlich von Pnuël. Heute: El-Jubeihat."] },
      { number: 12, text: "Das ganze Lager geriet in Panik, und die beiden Könige Sebach und Zalmunna flohen. Gideon verfolgte sie und nahm beide gefangen." },
      { number: 13, text: "Nach der Schlacht machte sich Gideon Ben-Joasch auf den Rückweg. Als er den Pass von Heres hinabstieg," },
      { number: 14, text: "griff er einen jungen Burschen aus Sukkot auf. Er fragte ihn aus und ließ sich von ihm die Namen der führenden Männer und der Stadtoberen aufschreiben, insgesamt 77 Namen." },
      { number: 15, text: "Als er nach Sukkot kam, sagte er zu den Männern der Stadt: \"Hier sind Sebach und Zalmunna, mit denen ihr mich verspottet und gesagt habt: 'Hast du Sebach und Zalmunna denn schon in der Hand? Warum sollen wir deiner erschöpften Truppe Brot geben?'" },
      { number: 16, text: "Dann ließ er die führenden Männer der Stadt ergreifen und zahlte es ihnen mit Wüstendorn und Stechdisteln heim." },
      { number: 17, text: "In Pnuël ließ er die Männer der Stadt erschlagen und die Burg niederreißen." },
      { number: 18, text: "Schließlich wandte er sich an Sebach und Zalmunna: \"Wie sahen die Männer aus, die ihr am Berg Tabor erschlagen habt?\" – \"Sie waren wie du\", antworteten sie, \"jeder sah aus wie ein Königssohn.\"" },
      { number: 19, text: "Da rief Gideon: \"Es waren meine eigenen Brüder! So wahr Jahwe lebt: Hättet ihr sie am Leben gelassen, würde ich euch nicht umbringen!\"" },
      { number: 20, text: "Er wandte sich an Jeter, seinen ältesten Sohn: \"Töte sie!\" Doch Jeter war noch jung und zögerte, sein Schwert zu ziehen; er hatte Angst davor." },
      { number: 21, text: "Da sagten Sebach und Zalmunna: \"Steh doch auf und tu es selbst! Hier braucht es den ganzen Mann!\" Da sprang Gideon auf und erschlug beide. Dann nahm er die Halbmonde an sich, die an den Hälsen ihrer Kamele hingen." },
      { number: 22, text: "Die Israeliten sagten zu Gideon: \"Du sollst unser Herrscher sein, du, dein Sohn und dein Enkel, denn du hast uns von den Midianitern befreit.\"", heading: "Gideons Efod" },
      { number: 23, text: "Doch Gideon erwiderte: \"Ich will nicht über euch herrschen, und auch mein Sohn soll es nicht; Jahwe soll euer König sein!" },
      { number: 24, text: "Ich habe jedoch eine Bitte an euch: Gebt mir die geweihten Ringe, die ihr erbeutet habt!\" Die Midianiter hatten nämlich goldene Ringe getragen, weil sie Ismaëliten waren." },
      { number: 25, text: "\"Das tun wir gern\", sagten sie. Sie breiteten einen Umhang aus, und jeder warf den Weihring von seiner Beute darauf." },
      { number: 26, text: "Das Gold, das auf diese Weise zusammenkam, wog etwa 20 Kilogramm*. Dazu kamen noch die Halbmonde, Ohrgehänge und Purpurkleider, die die Midianiterkönige getragen hatten, und der kostbare Halsschmuck der Kamele.", footnotes: ["20 Kilogramm. Wörtlich: 1700 Schekel. Nach archäologischen Funden kann das Durchschnittsgewicht eines Schekels mit 11,5 Gramm angenommen werden."] },
      { number: 27, text: "Gideon ließ daraus ein Efod* machen und stellte es in seiner Heimatstadt Ofra auf. Ganz Israel kam dorthin und verehrte es. Das wurde Gideon und seiner Familie zum Verhängnis.", footnotes: ["Efor. Es handelt sich offenbar um eine Nachbildung des hohenpriesterlichen Efods (2. Mose 39), das als Symbol für Jahwe verehrt wurde."] },
      { number: 28, text: "So wurden die Midianiter gezwungen, sich vor Israel zu beugen. Sie wagten nicht mehr, den Kopf hoch zu tragen. So lange Gideon lebte, hatte das Land Ruhe vor seinen Feinden, 40 Jahre lang.", heading: "Gideons Tod" },
      { number: 29, text: "Und Gideon Jerub-Baal Ben-Joasch kehrte nach Hause zurück." },
      { number: 30, text: "Von seinen vielen Frauen hatte er 70 Söhne." },
      { number: 31, text: "Eine seiner Nebenfrauen wohnte in Sichem. Sie bekam einen Sohn von ihm, den er Abimelech, \"mein Vater ist König\", nannte." },
      { number: 32, text: "Gideon starb in hohem Alter und wurde in der Grabstätte seines Vaters Joasch in Ofra, der Stadt der Abiëser-Sippe, beigesetzt." },
      { number: 33, text: "Bald nach Gideons Tod fingen die Israeliten wieder an, es mit den Baalen zu treiben, und machten sich den Baal-Berit zum Gott." },
      { number: 34, text: "Sie vergaßen Jahwe, ihren Gott, der sie aus der Gewalt aller ihrer Feinde ringsum gerettet hatte." },
      { number: 35, text: "Auch der Familie von Gideon, der auch Jerub-Baal genannt wurde, erwiesen sie keinen Dank für all das Gute, was er an Israel getan hatte. Das kam so:" },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Abimelech, der Sohn von Jerub-Baal* ging nach Sichem zu den Brüdern seiner Mutter und zu ihren anderen Verwandten und bat sie:", heading: "Abimelech wird König", footnotes: ["Jerub-Baal. Zweiter Name Gideons."] },
      { number: 2, text: "\"Fragt doch die Bürger von Sichem, ob es ihnen lieber ist, von 70 Männern regiert zu werden, von allen Söhnen Jerub-Baals oder nur von einem. Und erinnert sie daran, dass ich ja euer Fleisch und Blut bin.\"" },
      { number: 3, text: "Als die Brüder seiner Mutter vor den Bürgern Sichems auf diese Weise für Abimelech eintraten, ließen diese sich für ihn gewinnen, denn sie sagten sich: \"Er ist ja einer von uns!\"" },
      { number: 4, text: "Sie gaben ihm 70 Silberstücke* aus dem Tempel des Baal-Berit. Mit diesem Geld heuerte Abimelech eine Bande gewissenloser Männer an, die ihm folgten.", footnotes: ["Das waren noch keine Münzen, sondern Silberstücke mit festen Gewichtseinheiten."] },
      { number: 5, text: "Er zog mit ihnen nach Ofra, wo die Familie seines Vaters lebte, und brachte seine Brüder um. Alle 70 Söhne Jerub-Baals ließ er auf ein und demselben Felsblock öffentlich hinrichten. Nur Jerub-Baals jüngster Sohn Jotam kam mit dem Leben davon, weil er sich versteckt hatte." },
      { number: 6, text: "Danach versammelten sich alle Bürger von Sichem und die Besatzung der Festung bei der Terebinthe am Steinpfeiler von Sichem. Dort machten sie Abimelech zu ihrem König." },
      { number: 7, text: "Als Jotam davon erfuhr, stieg er auf den Gipfel des Berges Garizim und rief zu den Bürgern von Sichem hinüber:*.\"Hört auf mich, Bürger von Sichem, / damit Gott auch auf euch hört!", heading: "Jotams Fabel", footnotes: ["rief hinüber. Er sprach vielleicht von einem Felsvorsprung auf der einen Seite des Garizim, der im Volksmund \"Jotams Kanzel\" genannt wird. Das Gebiet zwischen Garizim und Ebal bildet ein natürliches Amphitheater mit erstaunlichen akustischen Eigenschaften."] },
      { number: 8, text: "Einst machten sich die Bäume auf / und wollten einen König über sich. / Sie sagten zum Olivenbaum: / \"Sei du der König über uns!\"" },
      { number: 9, text: "Da erklärte der Olivenbaum: / 'Sollte ich mein Fett aufgeben, / mit dem man Götter und Menschen ehrt, / und anfangen über euch zu thronen?'" },
      { number: 10, text: "Da sagten die Bäume zum Feigenbaum: / 'Komm, sei du der König über uns!'" },
      { number: 11, text: "Doch der Feigenbaum meinte: 'Soll mir denn die Süße stocken / und meine gute Frucht, / nur, damit ich über euch schwebe?" },
      { number: 12, text: "Dann wurde der Weinstock gefragt: / 'Willst du nicht unser König sein?'" },
      { number: 13, text: "Doch der Weinstock erklärte: / 'Soll ich meinen Wein aufgeben, / der Götter und Menschen erfreut, / und anfangen, über euch zu schweben?'" },
      { number: 14, text: "Nun fragten die Bäume den Wegdorn: / 'Komm, sei du der König über uns!'" },
      { number: 15, text: "Der Wegdorn sagte zu den Bäumen: / 'Wollt ihr wirklich mich als König über euch? / Nun denn, sucht unter meinem Schatten Schutz. / Sonst geht Feuer aus von mir / und frisst die Zedern Libanons.'" },
      { number: 16, text: "\"Hört zu!\", fuhr Jotam fort, \"War es wirklich recht von euch, Abimelech zu eurem König zu machen? Habt ihr vergessen, was ihr Jerub-Baal und seiner Familie verdankt?" },
      { number: 17, text: "Mein Vater hat für euch gekämpft und sein Leben aufs Spiel gesetzt, um euch von den Midianitern zu befreien." },
      { number: 18, text: "Aber ihr habt euch gegen seine Familie gestellt und seine Söhne erschlagen. 70 Mann habt ihr auf ein und demselben Felsblock hingerichtet. Und dann habt ihr diesen Abimelech, den Sohn seiner Sklavin, zum König von Sichem gemacht, nur weil er euer Bruder ist." },
      { number: 19, text: "Wenn das gut und richtig war, was ihr mit Jerub-Baal und seiner Familie gemacht habt, dann sollt ihr eure Freude an Abimelech haben und er an euch!" },
      { number: 20, text: "Wenn es aber Unrecht war, dann möge Feuer von Abimelech ausgehen und die Bürger von Sichem samt der Festungsbesatzung fressen. Und von den Bürgern Sichems und der Besatzung der Festung soll Feuer ausgehen und Abimelech fressen.\"" },
      { number: 21, text: "Dann machte sich Jotam davon und brachte sich vor seinem Bruder Abimelech nach Beer* in Sicherheit.", footnotes: ["Beer. Das heißt Brunnen, wie viele Orte in Israel."] },
      { number: 22, text: "Als Abimelech drei Jahre über Israel geherrscht hatte,", heading: "Abimelechs Ende" },
      { number: 23, text: "schickte Gott einen bösen Geist zwischen ihn und die Bürger von Sichem. Die Einwohner der Stadt lehnten sich gegen Abimelech auf." },
      { number: 24, text: "Er sollte nämlich für das Verbrechen an seinen eigenen Brüdern, den 70 Söhnen Jerub-Baals, bestraft werden. Und auch die Einwohner Sichems, die ihn dazu ermutigt hatten, sollten jetzt dafür büßen." },
      { number: 25, text: "Um den Hass auf Abimelech zu schüren, legten sich die Bürger Sichems auf den Bergen rings um ihre Stadt auf die Lauer. Sie raubten jeden aus, der vorüberkam. Das wurde Abimelech gemeldet." },
      { number: 26, text: "Um diese Zeit ließ sich Gaal Ben-Ebed mit seinen Brüdern in Sichem nieder und gewann das Vertrauen der Bürger." },
      { number: 27, text: "Nach der Weinlese, als sie neuen Wein gekeltert hatten, veranstalteten sie ein Freudenfest im Tempel ihres Gottes. Sie aßen und tranken und verwünschten Abimelech." },
      { number: 28, text: "\"Wer ist schon Abimelech?\", rief Gaal übermütig. \"Und wer ist Sichem, dass sie dem Sohn des Jerub-Baal dienen sollte? Sollen wir etwa diesem Sebul gehorchen, den er uns als Aufpasser vor die Nase gesetzt hat? Dienen wir lieber den Nachkommen von Hamor, dem Gründer der Stadt! Wozu sollten wir Abimelech folgen?" },
      { number: 29, text: "Wenn ich hier das Sagen hätte, würde ich Abimelech schon beseitigen. Ich würde ihm sagen: 'Ruf deine Truppe zusammen und stell dich zum Kampf!'\"" },
      { number: 30, text: "Als der Stadthauptmann Sebul hörte, was Gaal gesagt hatte, wurde er zornig" },
      { number: 31, text: "und schickte heimlich Boten zu Abimelech. Die sollten ihm ausrichten: \"Gaal Ben-Ebed ist mit seinen Brüdern nach Sichem gekommen und wiegelt die Stadt gegen dich auf." },
      { number: 32, text: "Bring deshalb im Schutz der Nacht deine Truppen her und haltet euch in der Nähe der Stadt versteckt." },
      { number: 33, text: "Bei Sonnenaufgang greifst du die Stadt an. Wenn Gaal dir dann mit seinen Leuten entgegenzieht, kannst du mit ihm abrechnen.\"" },
      { number: 34, text: "Abimelech brach sofort auf und zog in der Nacht mit seinen Truppen herbei. Er teilte sie in vier Gruppen ein, die sich um Sichem herum versteckten." },
      { number: 35, text: "Als Gaal am Morgen aus dem Stadttor trat, brachen Abimelech und seine Männer aus ihren Verstecken hervor." },
      { number: 36, text: "Gaal entdeckte sie und sagte zu Sebul: \"Siehst du das? Da steigen doch Truppen von den Bergen herab!\" – \"Du hältst den Schatten der Berge für Männer\", entgegnete ihm dieser." },
      { number: 37, text: "Doch Gaal beharrte darauf: \"Schau doch nur, da kommen Krieger vom Nabel des Landes* herab! Und dort kommt eine Abteilung auf dem Weg vom Orakelbaum her!\"", footnotes: ["Nabel des Landes. Der runde Gipfel des Garizim, galt als zentraler Berg des kanaanitischen Berglandes."] },
      { number: 38, text: "Da sagte Sebul zu ihm: \"Wo ist nun dein Großmaul geblieben, das so sicher verkündet hat: 'Wer ist schon Abimelech, dass wir ihm dienen sollten!'? Ja, dort kommen die Leute, die du verspottet hast. Zieh nur los und kämpfe mit ihnen!\"" },
      { number: 39, text: "Da rückte Gaal an der Spitze der Bürger von Sichem aus und kämpfte gegen Abimelech." },
      { number: 40, text: "Doch der trieb sie in die Stadt zurück, sodass der Weg bis ans Tor mit Leichen übersät war." },
      { number: 41, text: "Abimelech kehrte mit seinen Truppen nach Aruma* zurück. Sebul aber vertrieb Gaal und seine Brüder aus Sichem.", footnotes: ["Aruma. Wird mit Kirbet el-Urma, zwischen Sichem und Schilo identifiziert, etwa 9 km von Sichem entfernt."] },
      { number: 42, text: "Am nächsten Morgen gingen die Leute von Sichem wieder auf ihre Felder hinaus. Abimelech hörte davon." },
      { number: 43, text: "Er teilte seine Truppen in drei Abteilungen und legte sich auf dem freien Feld in einen Hinterhalt. Als er die Leute wieder aus der Stadt herauskommen sah, brach er hervor und schlug sie nieder." },
      { number: 44, text: "Mit einer Abteilung stürmte er vor und besetzte das Stadttor. Die anderen beiden Abteilungen trieben die Leute auf den Feldern zusammen und erschlugen sie." },
      { number: 45, text: "Den ganzen Tag lang kämpfte Abimelech gegen die Stadt. Als er sie erobert hatte, ließ er alle Bewohner töten. Dann zerstörte er die Stadt und streute Salz* auf die Trümmer.", footnotes: ["streute Salz. Er tat das offenbar, um sie zu bleibender Unfruchtbarkeit zu verdammen, siehe 5. Mose 29,22; Jeremia 17,6."] },
      { number: 46, text: "Als die Bewohner der Burg hörten, wie Abimelech in die Stadt einbrach, hatten sie sich in das Kellergewölbe unter dem Tempel des Baal-Berit geflüchtet." },
      { number: 47, text: "Sobald Abimelech das gemeldet wurde," },
      { number: 48, text: "ging er mit den Leuten, die er bei sich hatte, zum Berg Zalmon*, hieb mit der Axt einen Ast vom Baum und nahm ihn auf die Schulter. \"Macht es mir nach!\", rief er. \"Aber schnell!\"", footnotes: ["Zalmon. Offenbar ein bewaldeter Hügel in der Nähe der Stadt. Hebr. Zalmon = Beschatter."] },
      { number: 49, text: "Jeder seiner Leute hackte seinen Ast ab und schleppte ihn hinter Abimelech her. Sie schichteten alles Holz über dem Kellergewölbe auf und steckten es in Brand. So starben alle Bewohner der Tempelburg, etwa tausend Männer und Frauen." },
      { number: 50, text: "Anschließend zog Abimelech gegen Tebez*. Er belagerte die Stadt und nahm sie ein.", footnotes: ["Tebez. Heute: Tubas, 15 km nordöstlich von Nablus (Sichem)."] },
      { number: 51, text: "Mitten in der Stadt lag jedoch eine stark befestigte Burg. Alle Bewohner, Männer wie Frauen, waren dort hinein geflüchtet. Sie hatten die Tore geschlossen und waren auf das flache Dach gestiegen." },
      { number: 52, text: "Abimelech versuchte, die Burg zu erobern. Als er sich dem Tor näherte, um es in Brand zu stecken," },
      { number: 53, text: "warf eine Frau den Drehstein einer Handmühle auf seinen Kopf und zerschmetterte ihm den Schädel." },
      { number: 54, text: "Schnell rief er seinen jungen Waffenträger herbei und sagte: \"Zieh dein Schwert und töte mich! Sonst wird es heißen: 'Eine Frau hat ihn umgebracht.'\" Sein Waffenträger gehorchte und erstach ihn." },
      { number: 55, text: "Als die Israeliten sahen, dass Abimelech tot war, kehrte jeder wieder nach Hause zurück." },
      { number: 56, text: "So ließ Gott das Verbrechen von Abimelech, das er an seinem Vater begangen hatte, als er seine 70 Brüder umbrachte, auf ihn selbst zurückfallen." },
      { number: 57, text: "Auch auf die Bewohner von Sichem ließ Gott ihre Bosheit zurückfallen, und der Fluch, den Jotam Ben-Jerub-Baal über sie ausgesprochen hatte, ging in Erfüllung." },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Nach Abimelech stand Tola Ben-Pua auf, um Israel zu helfen. Er stammte aus Issachar und wohnte in Schamir*, im Gebirge Efraïm. Sein Großvater hieß Dodo.", heading: "Die Richter Tola und Jaïr", footnotes: ["Schamir. Der Ort lag wahrscheinlich an der Stelle des späteren Samaria."] },
      { number: 2, text: "23 Jahre lang war er der Richter Israels. Dann starb er und wurde in Schamir begraben." },
      { number: 3, text: "Nach ihm stand Jaïr aus Gilead, dem Ostjordanland, auf. Er war 22 Jahre Richter in Israel" },
      { number: 4, text: "und hatte dreißig Söhne, die auf dreißig Eseln ritten und dreißig Ortschaften besaßen. Man nennt sie bis heute die \"Zeltdörfer Jaïrs\". Sie liegen in Gilead, dem Ostjordanland." },
      { number: 5, text: "Als Jaïr starb, wurde er in Kamon* begraben.", footnotes: ["Kamon. Vielleicht identisch mit Qamm."] },
      { number: 6, text: "Und wieder taten die Israeliten, was Jahwe als böse ansah. Sie dienten den Baalen, den Astarten, den Göttern der Syrer und Sidonier, den Göttern der Moabiter, Ammoniter und Philister. Sie kehrten Jahwe den Rücken und wollten nichts mehr von ihm wissen.", heading: "Von den Ammonitern unterdrückt" },
      { number: 7, text: "Da flammte Jahwes Zorn gegen Israel auf. Er gab sie in die Gewalt der Philister und der Ammoniter." },
      { number: 8, text: "Noch im selben Jahr eroberten die Ammoniter das Gebiet in Gilead, in dem sie früher gelebt hatten, und unterdrückten die Israeliten dort grausam." },
      { number: 9, text: "Die Ammoniter überschritten sogar den Jordan und griffen die Stämme Juda, Benjamin und Efraïm an. So gerieten die Israeliten in große Bedrängnis." },
      { number: 10, text: "Da schrien sie zu Jahwe um Hilfe. \"Wir haben gegen dich gesündigt!\", riefen sie. \"Dich, unseren Gott, haben wir verlassen und den Baalen gedient!\"" },
      { number: 11, text: "Jahwe antwortete: \"Habe ich euch nicht von den Ägyptern befreit, den Amoritern, Ammonitern und Philistern?" },
      { number: 12, text: "Habe ich euch nicht gerettet, als ihr wegen der Sidonier zu mir geschrien habt, und als die Amalekiter und Maoniter* euch quälten?", footnotes: ["Maoniter. Das meint nach der LXX vielleicht die Midianiter."] },
      { number: 13, text: "Doch ihr habt mich verlassen und anderen Göttern gedient. Darum werde ich euch jetzt nicht mehr helfen." },
      { number: 14, text: "Geht und schreit doch zu den Göttern, die ihr euch ausgesucht habt! Sollen sie euch doch retten aus eurer Not!\"" },
      { number: 15, text: "Da sagten die Israeliten zu Jahwe: \"Wir haben gesündigt. Bestrafe uns, wenn du willst, aber rette uns diesmal noch!\"" },
      { number: 16, text: "Darauf entfernten sie die fremden Götterbilder aus ihrer Mitte und verehrten Jahwe. Da konnte er das Elend Israels nicht länger ertragen." },
      { number: 17, text: "Die Ammoniter hatten ihre Truppen zusammengezogen und ihr Lager in Gilead aufgeschlagen. Die Männer Israels hatten ein Lager bei Mizpa* bezogen.", heading: "Jiftach wird Richter", footnotes: ["Mizpa. D.h. Wachtturm. Verschiedene Orte trugen diesen Namen. Gemeint ist wahrscheinlich das, wo Jakob und Laban einst einen Steinhaufen errichteten (1. Mose 31,45-49)."] },
      { number: 18, text: "Da sagten sich die führenden Männer von Gilead*: \"Wir brauchen einen Heerführer, der den Kampf gegen die Ammoniter aufnimmt.\" Und sie beschlossen: \"Diesen Mann werden wir zum Oberhaupt aller Bewohner Gileads machen.\"", footnotes: ["Männer von Gilead. Das müssen Vertreter der Stämme Ruben, Gad und Ost-Manasse gewesen sein, die in diesem Gebiet lebten."] },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Nun gab es dort einen ausgezeichneten Krieger namens Jiftach. Allerdings war er der Sohn einer Prostituierten mit einem Mann namens Gilead." },
      { number: 2, text: "Dieser Gilead hatte auch Söhne von seiner Ehefrau. Als diese herangewachsen waren, vertrieben sie Jiftach: \"Du hast keinen Anteil an unserem Familienbesitz\", sagten sie, \"denn du stammst von einer anderen Frau.\"" },
      { number: 3, text: "So war Jiftach von seinen Brüdern weggegangen und lebte im Gebiet von Tob*. Er sammelte Männer um sich, die nichts mehr zu verlieren hatten, und durchstreifte mit ihnen das Land.", footnotes: ["Tob. Gebiet um die Stadt Tob, nördlich vom Königreich Ammon und östlich vom Stammesgebiet Manasses."] },
      { number: 4, text: "Einige Zeit später hatten die Ammoniter den Krieg mit Israel angefangen." },
      { number: 5, text: "Da machten sich die führenden Männer von Gilead auf den Weg, um Jiftach aus dem Land Tob zurückzuholen." },
      { number: 6, text: "\"Komm, sei du unser Anführer gegen die Ammoniter!\", sagten sie zu ihm." },
      { number: 7, text: "Doch Jiftach entgegnete: \"Habt ihr mich nicht verachtet und aus dem Haus meines Vaters vertrieben? Und jetzt, wo ihr in Not seid, kommt ihr ausgerechnet zu mir?\"" },
      { number: 8, text: "Doch die Ältesten von Gilead erwiderten: \"Wir haben dich aufgesucht, damit du mit uns gegen die Ammoniter kämpfst. Du sollst unser Oberhaupt und Anführer aller Bewohner Gileads werden.\"" },
      { number: 9, text: "\"Ihr meint also, wenn Jahwe mir den Sieg über die Ammoniter schenkt, soll ich tatsächlich euer Oberhaupt werden?\", fragte Jiftach." },
      { number: 10, text: "\"Ja\", sagten die Ältesten, \"wir schwören es vor Jahwe! So soll es geschehen!\"" },
      { number: 11, text: "Da ging Jiftach mit den Ältesten von Gilead, und das Volk setzte ihn als Oberhaupt und Anführer ein. Und in Mizpa brachte Jiftach noch einmal alle seine Anliegen vor Jahwe." },
      { number: 12, text: "Dann schickte Jiftach Boten zum König der Ammoniter und ließ ihm sagen: \"Warum führst du Krieg gegen mein Land? Was ist zwischen uns passiert?\"", heading: "Verhandlung mit dem König von Ammon" },
      { number: 13, text: "Der König ließ ihm antworten: \"Weil Israel mir mein Land genommen hat, als es aus Ägypten kam, das ganze Gebiet zwischen den Flüssen Arnon* und Jabbok* und im Westen bis an den Jordan. Gebt mir das Land jetzt freiwillig zurück!\"", footnotes: ["Arnon. Fluss, etwa 44 km lang. Er mündet ins Tote Meer und bildete die Südgrenze Israels im Ostjordangebiet.", "Jabbok. Fluss, mündet etwa 80 km nördlich vom Arnon in den Jordan."] },
      { number: 14, text: "Da schickte Jiftach noch einmal Boten an den ammonitischen König" },
      { number: 15, text: "und ließ ihm sagen: \"So spricht Jiftach: Israel hat weder das Land Moab noch das der Ammoniter an sich genommen." },
      { number: 16, text: "Es war vielmehr so: Als Israel Ägypten verlassen hatte, durchquerte es die Wüste bis zum Schilfmeer und kam bis nach Kadesch*.", footnotes: ["Kadesch. Im Süden des Negev an der Grenze zum Königreich Edom, etwa 80 km südwestlich von Beerscheba."] },
      { number: 17, text: "Von dort schickte Israel Boten zum König von Edom und bat ihn, durch sein Land ziehen zu dürfen. Doch der erlaubte es nicht. Auch zum König von Moab schickte Israel Boten. Aber auch der wollte nicht. So blieben die Israeliten in Kadesch." },
      { number: 18, text: "Später umgingen sie das Land der Edomiter* und Moabiter auf dem Weg durch die Wüste und kamen dann von Osten wieder an die Grenze des Landes Moab, an den Arnon. Sie drangen jedoch nicht ins Land ein, sondern lagerten östlich vom Fluss.", footnotes: ["Die Edomiter waren Nachkommen Esaus und bewohnten das Land östlich der Araba und südlich vom Toten Meer."] },
      { number: 19, text: "Dann schickten sie Boten zum Amoriterkönig Sihon nach Heschbon* und baten ihn, durch sein Land bis an ihren Bestimmungsort ziehen zu dürfen.", footnotes: ["Heschbon. Die Stadt liegt 25 km östlich der Jordanmündung ins Tote Meer, 19 km südwestlich von Rabba (heute Amman)."] },
      { number: 20, text: "Doch Sihon glaubte nicht, dass Israel nur durch sein Land ziehen wollte, und rief alle seine Truppen nach Jahaz* zusammen und kämpfte gegen Israel.", footnotes: ["Jahaz. Moabitische Stadt auf der Hochfläche des Ostjordanlandes, östlich vom Toten Meer."] },
      { number: 21, text: "Aber Jahwe, Israels Gott, gab Sihon und sein ganzes Heer in Israels Hand. So konnte es das Land der Amoriter in Besitz nehmen, denn die Amoriter wohnten damals" },
      { number: 22, text: "in diesem Gebiet, das vom Fluss Arnon bis an den Jabbok und von der Wüste bis an den Jordan reichte." },
      { number: 23, text: "Jahwe, der Gott Israels, hat die Amoriter vor seinem Volk vertrieben, und da willst du uns wieder aus diesem Land verdrängen?" },
      { number: 24, text: "Wenn dein Gott Kemosch jemand vor dir vertreibt, dann nimmst du doch auch sein Land in Besitz. Und wenn unser Gott Jahwe irgendjemand vor uns vertreibt, machen wir es genauso. Wir nehmen sein Land in Besitz." },
      { number: 25, text: "Glaubst du wirklich, dass du besser bist als Balak Ben-Zippor, der König von Moab*? Hat er es vielleicht gewagt, einen Streit mit Israel anzufangen oder gar einen Krieg?", footnotes: ["Balak ... Moab. Siehe 4. Mose 22-24."] },
      { number: 26, text: "Dreihundert Jahre lang wohnte Israel in Heschbon und Aroer* und den dazugehörigen Ortschaften und in all den Städten am Arnon. Warum habt ihr uns diese in all den Jahren nicht weggenommen?", footnotes: ["Aroer. Stadt am Nordufer des Arnon."] },
      { number: 27, text: "Ich habe dir kein Unrecht getan, sondern du tust Unrecht, wenn du ohne Ursache Krieg anfängst. Jahwe ist Richter! Er soll jetzt zwischen Israel und Ammon entscheiden.\"" },
      { number: 28, text: "Doch der König von Ammon hörte nicht auf die Botschaft Jiftachs." },
      { number: 29, text: "Da kam der Geist Jahwes über Jiftach. Er durchzog das ganze Gebiet von Gilead und Manasse, um seine Truppen zu sammeln, und kehrte dann nach Mizpa zurück. Von dort aus zog er in den Kampf gegen die Ammoniter.", heading: "Sieg über die Ammoniter" },
      { number: 30, text: "Dabei gelobte er Jahwe: \"Wenn du die Ammoniter wirklich in meine Hand gibst," },
      { number: 31, text: "und ich wohlbehalten zurückkehre, dann soll das, was mir als Erstes aus der Haustür entgegenkommt, dir, Jahwe, gehören. Ich will es dir als Opfer verbrennen.\"" },
      { number: 32, text: "Dann zog Jiftach in den Kampf gegen die Ammoniter. Und Jahwe gab sie in seine Gewalt." },
      { number: 33, text: "Er besiegte sie von Aroer an bis nach Minnit* und eroberte zwanzig Städte bis nach Abel-Keramim*. Das war eine vernichtende Niederlage für die Ammoniter, und sie mussten sich vor den Israeliten beugen.", footnotes: ["Minnit. Ammonitischer Ort an der Straße von Heschbon nach Rabba.", "Abel-Keramim liegt 8 km südlich von Rabba."] },
      { number: 34, text: "Dann kehrte Jiftach nach Mizpa zurück. Als er sich seinem Haus näherte, lief seine Tochter tanzend und das Tamburin schlagend heraus, ihm entgegen. Es war seine einzige; er hatte sonst kein Kind." },
      { number: 35, text: "Als er sie sah, zerriss er vor Schmerz sein Gewand* und rief: \"Ach, meine Tochter, du brichst mir das Herz! Dass gerade du es sein musst, die mich ins Unglück stürzt! Ich habe Jahwe mein Wort gegeben, und ich kann nicht zurück!\"", footnotes: ["zerriss ... Gewand. Trauerbrauch – man riss das Gewand vom Halssaum an auf und entblößte die Brust."] },
      { number: 36, text: "Doch sie sagte zu ihm: \"Mein Vater, wenn du Jahwe etwas versprochen hast, dann tu an mir, was du gelobt hast! Jahwe hat dir ja auch den Sieg über deine Feinde, die Ammoniter, geschenkt.\"" },
      { number: 37, text: "Dann fügte sie hinzu: \"Nur eine Bitte habe ich: Gib mir noch zwei Monate Zeit. Ich möchte mit meinen Freundinnen in die Berge gehen und meine Jungfrauschaft betrauern.\"" },
      { number: 38, text: "\"Geh nur\", sagte ihr Vater, und gab ihr zwei Monate Zeit. So ging sie mit ihren Freundinnen in die Berge und weinte darüber, nie verheiratet gewesen zu sein." },
      { number: 39, text: "Als die zwei Monate um waren, kehrte sie zu ihrem Vater zurück, und er erfüllte sein Gelübde an ihr. Sie hatte nie mit einem Mann geschlafen. Daraus entstand in Israel der Brauch," },
      { number: 40, text: "dass die jungen Frauen jedes Jahr vier Tage lang zusammen weggehen und die Tochter Jiftachs von Gilead besingen." },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Die Männer des Stammes Efraïm sammelten sich*, zogen über den Jordan nach Norden und machten Jiftach schwere Vorwürfe: \"Warum bist du ohne uns gegen die Ammoniter in den Krieg gezogen? Warum hast du uns nicht zu Hilfe gerufen? Wir werden dir das Haus über dem Kopf anzünden!\"", heading: "Jiftach gegen den Stamm Efraïm", footnotes: ["sammelten sich. Sie strebten wahrscheinlich nach der Vorherrschaft über die Stämme Israels."] },
      { number: 2, text: "Da sagte Jiftach: \"Ich musste mit meinen Leuten einen schweren Kampf gegen die Ammoniter bestehen. Ich habe euch ja gerufen, aber ihr habt mir nicht geholfen." },
      { number: 3, text: "Als mir klar wurde, dass ich nicht mit euch rechnen konnte, wagte ich mein Leben. Ich zog gegen die Ammoniter und habe sie mit Jahwes Hilfe besiegt. Warum kommt ihr jetzt und bedroht mich?\"" },
      { number: 4, text: "Jiftach rief die Männer Gileads zusammen und kämpfte mit ihnen gegen den Stamm Efraïm. Sie waren erbittert, weil die Männer von Efraïm gesagt hatten: \"Ihr seid ja nur Flüchtlinge aus Efraïm! Gilead liegt doch mitten zwischen Efraïm und Manasse!\" Die Gileaditer besiegten die Efraïmiten" },
      { number: 5, text: "und besetzten dann die Furten des Jordan. Wenn nun ein efraïmitischer Flüchtling bat: \"Lasst mich hinüber!\", dann fragten sie ihn: \"Stammst du aus Efraïm?\" Wenn er das verneinte," },
      { number: 6, text: "forderten sie ihn auf: \"Sag doch einmal Schibbolet, Wasserschwall!\" Sagte er dann \"Sibbolet\", weil er es nicht richtig aussprechen* konnte, packten sie ihn und machten ihn an Ort und Stelle nieder. Auf diese Weise wurden damals 42.000 Männer aus Efraïm an den Jordanübergängen getötet.", footnotes: ["aussprechen. Im Dialekt Efraïms wurde \"s\" statt \"sch\" gesprochen."] },
      { number: 7, text: "Sechs Jahre lang war Jiftach Israels Richter. Als er starb, wurde er in einer der Städte Gileads begraben." },
      { number: 8, text: "Nach ihm war Ibzan von Bethlehem* Richter von Israel.", heading: "Die Richter Ibzan, Elon und Abdon", footnotes: ["Bethlehem – Stadt im Gebiet des Stammes Juda, 8 km südlich von Jerusalem."] },
      { number: 9, text: "Er hatte dreißig Söhne und dreißig Töchter. Alle Töchter verheiratete er nach auswärts, und dreißig Töchter führte er von auswärts seinen Söhnen zu. Sieben Jahre lang war er der Richter Israels," },
      { number: 10, text: "dann starb er und wurde in Bethlehem begraben." },
      { number: 11, text: "Nach ihm übernahm Elon aus dem Stamm Sebulon das Richteramt. Er war zehn Jahre Richter über Israel." },
      { number: 12, text: "Als er starb, wurde er in Ajalon, im Gebiet Sebulons, begraben." },
      { number: 13, text: "Sein Nachfolger war Abdon Ben-Hillel aus Piraton." },
      { number: 14, text: "Er hatte 40 Söhne und 30 Enkel, die auf 70 Eseln ritten. Acht Jahre war er Richter über Israel." },
      { number: 15, text: "Als er starb, wurde er in Piraton, im Gebiet Efraïms, am Amalekiterberg begraben." },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Wieder taten die Israeliten, was vor Jahwe böse war. Da gab er sie 40 Jahre lang in die Gewalt der Philister.", heading: "Die Geburt Simsons" },
      { number: 2, text: "Zu dieser Zeit lebte in Zora ein Mann aus dem Stamm Dan. Er hieß Manoach. Seine Frau konnte keine Kinder bekommen." },
      { number: 3, text: "Eines Tages erschien der Engel Jahwes der Frau und sagte: \"Du konntest bisher keine Kinder bekommen, aber jetzt wirst du schwanger werden und einen Sohn zur Welt bringen." },
      { number: 4, text: "Pass auf, dass du während der Schwangerschaft weder Wein noch Bier trinkst und auch nichts Unreines isst." },
      { number: 5, text: "Denn dein Sohn wird schon im Mutterleib ein Nasiräer, ein Gott Geweihter, sein. Niemals dürfen ihm die Haare geschnitten werden. Er wird anfangen, Israel aus der Gewalt der Philister zu retten.\"" },
      { number: 6, text: "Da lief die Frau zu ihrem Mann und sagte: \"Ein Gottesmann ist zu mir gekommen. Er sah aus wie der Engel Gottes selbst, und ich bekam es mit der Angst zu tun. Ich wagte nicht einmal, ihn zu fragen, woher er kommt. Und er hat mir seinen Namen auch nicht gesagt." },
      { number: 7, text: "Aber er sagte zu mir: 'Du wirst schwanger werden und einen Sohn bekommen. Von jetzt an darfst du weder Wein noch Bier trinken und auch nichts Unreines essen, denn dein Sohn wird von Mutterleib an bis zum Tag seines Todes ein Nasiräer sein.'\"" },
      { number: 8, text: "Da betete Manoach zu Jahwe und sagte: \"Herr, schick deinen Boten doch bitte noch einmal zu uns, damit er uns genau sagt, was wir mit dem Jungen tun sollen, den wir bekommen werden.\"" },
      { number: 9, text: "Gott hörte auf Manoach, und der Engel Gottes kam noch einmal zu der Frau, als sie gerade allein auf dem Feld war." },
      { number: 10, text: "Da lief sie schnell zu ihrem Mann und sagte: \"Eben ist der Mann, der damals zu mir gekommen ist, wieder erschienen!\"" },
      { number: 11, text: "Manoach stand auf und folgte seiner Frau. Als er zu dem Mann kam, fragte er: \"Bist du es, der neulich mit meiner Frau gesprochen hat?\" – \"Ja, ich bin es\", erwiderte er." },
      { number: 12, text: "Da fragte Manoach: \"Wenn deine Ankündigung eintrifft, wie sollen wir es dann mit dem Jungen halten? Was darf er tun und was nicht?\"" },
      { number: 13, text: "Der Engel Jahwes erwiderte: \"Deine Frau soll alles meiden, was ich ihr genannt habe." },
      { number: 14, text: "Sie darf nichts zu sich nehmen, was vom Weinstock kommt. Sie soll weder Wein noch Bier trinken und nichts Unreines essen und soll alle meine Anweisungen befolgen.\"" },
      { number: 15, text: "\"Bleib doch noch ein wenig hier\", sagte Manoach zum Engel Jahwes, \"wir möchten dir gern ein Ziegenböckchen zubereiten.\"" },
      { number: 16, text: "Doch der Engel Jahwes erwiderte: \"Auch wenn du mich drängst, würde ich von deiner Speise nichts essen. Doch wenn du willst, kannst du es Jahwe als Brandopfer bringen.\" Manoach hatte nämlich noch nicht erkannt, dass er es mit dem Engel Jahwes zu tun hatte." },
      { number: 17, text: "Deshalb fragte er: \"Wie heißt du? Wir wollen dich ehren, wenn deine Ankündigung eintrifft.\"" },
      { number: 18, text: "Doch der Engel Jahwes erwiderte: \"Was fragst du mich nach meinem Namen? Er ist zu wunderbar!\"" },
      { number: 19, text: "Da nahm Manoach das Ziegenböckchen und brachte es ihm auf einem Felsblock zusammen mit dem Brot als Opfer dar. Dann tat Jahwe etwas Wunderbares, bei dem Manoach und seine Frau zusehen konnten." },
      { number: 20, text: "Als nämlich die Flamme vom Altar in den Himmel stieg, stieg der Engel Jahwes in der Flamme mit nach oben. Da warfen sich Manoach und seine Frau erschrocken zu Boden." },
      { number: 21, text: "Sie sahen ihn nie wieder, doch Manoach begriff jetzt, dass es der Engel Jahwes gewesen war." },
      { number: 22, text: "Bestürzt sagte er zu seiner Frau: \"Jetzt müssen wir sterben! Wir haben ja Gott gesehen!\"" },
      { number: 23, text: "Aber seine Frau entgegnete: \"Wenn Jahwe uns hätte töten wollen, dann hätte er nicht das Brand- und Speisopfer von uns angenommen. Dann hätte er uns auch nicht all das sehen und so eine Ankündigung hören lassen.\"" },
      { number: 24, text: "Die Frau brachte einen Sohn zur Welt und nannte ihn Simson. Der Junge wuchs heran, und Jahwe segnete ihn." },
      { number: 25, text: "Dann fing der Geist Jahwes an, ihn umzutreiben. Das geschah im Lager Dans, zwischen Zora und Eschtaol." },
    ] },
    { number: 14, verses: [
      { number: 1, text: "Als Simson einmal nach Timna* hinunterging, sah er dort eine junge Philisterin, die ihm gut gefiel.", heading: "Simsons Hochzeit", footnotes: ["Timna liegt im Hügelland Judas, etwa 35 km westlich von Jerusalem."] },
      { number: 2, text: "Er ging nach Hause und sagte zu seinen Eltern: \"Ich habe in Timna eine junge Philisterin gesehen. Sorgt dafür, dass ich sie heiraten kann!\"" },
      { number: 3, text: "Seine Eltern erwiderten: \"Gibt es denn in unserem Stamm und in unserem ganzen Volk kein Mädchen für dich? Musst du unbedingt eine Philisterin zur Frau nehmen, eine von diesen Unbeschnittenen*?\" Doch Simson sagte zu seinem Vater: \"Sorge dafür, dass ich sie bekomme! Sie gefällt mir!\"", footnotes: ["Unbeschnittenen. Verächtlicher Ausdruck für Menschen, die nicht zum Bund Gottes gehörten. Siehe (1. Mose 17,9-14)."] },
      { number: 4, text: "Seine Eltern konnten nicht wissen, dass das von Jahwe so geplant war, weil er einen Anlass haben wollte, gegen die Philister vorzugehen, die damals über Israel herrschten." },
      { number: 5, text: "Simson machte sich also mit seinem Vater und seiner Mutter auf den Weg. In der Nähe der Weinberge von Timna – Simson war vom Weg abgebogen – stand ihm plötzlich ein junger Löwe brüllend gegenüber." },
      { number: 6, text: "Da kam der Geist Jahwes über Simson. Er packte den Löwen und zerriss ihn mit bloßen Händen, als würde er ein Ziegenböckchen zerlegen. Seinen Eltern erzählte er aber nichts davon." },
      { number: 7, text: "Als er nach Timna kam, sprach er mit der Philisterin. Sie gefiel ihm gut." },
      { number: 8, text: "Einige Zeit später ging er wieder nach Timna, um die Hochzeit zu feiern. Dabei bog er vom Weg ab, um nach dem toten Löwen zu sehen. Da fand er in dem vertrockneten Kadaver einen Bienenschwarm und Honig." },
      { number: 9, text: "Er löste den Honig heraus und begann, im Weitergehen davon zu essen. Dann ging er zu seinem Vater und seiner Mutter und gab ihnen ebenfalls davon. Er sagte ihnen aber nicht, dass er den Honig aus dem Kadaver des Löwen herausgeschält hatte." },
      { number: 10, text: "In Timna kümmerte sich sein Vater um den Ehevertrag*, während Simson ein Trinkgelage vorbereitete, wie die jungen Leute das eben so machten.", footnotes: ["Ehevertrag. Es handelte sich wahrscheinlich um eine sadiqa-Ehe, bei der die Frau in ihrer eigenen Familie blieb und von ihrem Ehemann nur von Zeit zu Zeit besucht wurde (Richter 15,1). Die Kinder gehörten dann zur Familie der Mutter. Ähnlich war es wohl bei der Nebenfrau Gideons, die in Sichem wohnte (Richter 8,31)."] },
      { number: 11, text: "Sobald Simson angekommen war, stellten sie ihm dreißig junge Männer* an die Seite.", footnotes: ["junge Männer. Die Gefährten des Bräutigams, früher vielleicht eine Art symbolische Leibwache; hier scheint sie eher die Anwesenden vor dem Bräutigam geschützt zu haben."] },
      { number: 12, text: "Simson sagte zu ihnen: \"Ich will euch ein Rätsel aufgeben. Wenn ihr es innerhalb der Festwoche lösen könnt, werde ich jedem von euch ein Leinenhemd und ein Festgewand geben." },
      { number: 13, text: "Wenn ihr es aber nicht herausbekommt, dann müsst ihr mir dreißig Leinenhemden und dreißig Festgewänder geben.\" – \"Gut\", sagten sie, \"lass uns dein Rätsel hören!\"" },
      { number: 14, text: "Er sagte: \"Vom Fresser kam Fraß, vom Starken kam Süßes.\" Drei Tage lang grübelten sie über dem Rätsel und konnten es nicht lösen." },
      { number: 15, text: "Am siebten Tag bedrohten sie Simsons Frau: \"Bring deinen Mann dazu, dir die Lösung zu verraten, und sag sie uns, sonst werden wir dich mit der ganzen Familie deiner Eltern verbrennen. Habt ihr uns denn eingeladen, um uns arm zu machen?\"" },
      { number: 16, text: "Simsons Frau brach in Tränen aus, als sie bei ihrem Mann war. \"Verabscheust du mich denn so?\", schluchzte sie. \"Du liebst mich ja gar nicht! Du hast meinen Landsleuten ein Rätsel aufgegeben und verschweigst mir die Lösung.\" – \"Ich habe sie nicht einmal meinem Vater und meiner Mutter gesagt\", erwiderte er, \"warum sollte ich sie dann bei dir ausplaudern?\"" },
      { number: 17, text: "Sie hatte die ganze Festwoche geweint, wenn sie bei ihm war. Am siebten Tag schließlich verriet er ihr die Lösung, weil sie ihm so zusetzte. Und sie gab diese ihren Landsleuten weiter." },
      { number: 18, text: "Noch vor dem Sonnenuntergang sagten die Männer der Stadt zu Simson: \"Was ist süßer als Honig und stärker als ein Löwe?\" Simson erwiderte: \"Hättet ihr nicht mein Kälbchen genommen, wärt ihr nie auf die Lösung gekommen!\"" },
      { number: 19, text: "Da kam der Geist des Herrn über Simson. Er ging nach Aschkelon* hinunter, erschlug dort dreißig Männer, zog ihnen ihre Gewänder aus und brachte sie den jungen Männern, die sein Rätsel gelöst hatten. Dann kehrte er voller Zorn in das Haus seiner Eltern zurück.", footnotes: ["Aschkelon. Die Philisterstadt an der Küste war etwa 35 km entfernt."] },
      { number: 20, text: "Simsons Frau aber wurde mit dem Brautführer, einem der dreißig Männer, verheiratet." },
    ] },
    { number: 15, verses: [
      { number: 1, text: "Zur Zeit der Weizenernte wollte Simson seine Frau besuchen. Er brachte ihr ein Ziegenböckchen mit und sagte zu ihrem Vater: \"Lass mich zu meiner Frau in die Kammer!\" Doch ihr Vater ließ ihn nicht hinein.", heading: "Simsons Rache" },
      { number: 2, text: "\"Das geht nicht!\", sagte er. \"Ich habe sie deinem Brautführer gegeben, weil ich dachte, du wolltest nichts mehr mit ihr zu tun haben. Aber sieh doch! Ihre jüngere Schwester ist noch viel schöner als sie. Du kannst sie an ihrer Stelle haben.\"" },
      { number: 3, text: "\"Das werde ich euch Philistern heimzahlen\", rief Simson, \"und ihr seid selbst daran schuld!\"" },
      { number: 4, text: "Er zog los, fing 300 Füchse, band sie paarweise an den Schwänzen zusammen und steckte eine Fackel in den Knoten." },
      { number: 5, text: "Dann zündete er die Fackeln an und ließ die Füchse in das stehende Getreide der Philister laufen. So gingen die Garbenhaufen und das reife Getreide auf den Feldern in Flammen auf, ja selbst Weinberge und Olivenhaine." },
      { number: 6, text: "\"Wer hat das getan?\", fragten die Philister. Und bald kam es heraus: \"Es war Simson, der Schwiegersohn des Timniters. Das ist die Rache dafür, dass der ihm seine Frau weggenommen und sie dem Brautführer gegeben hat.\" Da zogen die Philister nach Timna und verbrannten die Frau und ihren Vater." },
      { number: 7, text: "\"Wenn ihr das so macht\", rief Simson da, \"werde ich erst aufhören, wenn ich mich an euch gerächt habe!\"" },
      { number: 8, text: "Er schlug sie gründlich zusammen, bis sie alle am Boden lagen, und zog sich dann in die Felsspalte bei Etam* zurück.", footnotes: ["Etam. Vermutlich die Felshöhle über dem Wadi Ismain, 4 km südöstlich von Zora."] },
      { number: 9, text: "Da fielen die Philister in Juda ein und schlugen in der Gegend von Lehi* ihr Lager auf.", footnotes: ["Lehi. Hebr. Kieferknochen, vermutlich in der Nähe von Etam."] },
      { number: 10, text: "\"Warum seid ihr gegen uns heraufgezogen?\", fragten die Männer von Juda. Sie erwiderten: \"Wir wollen Simson gefangen nehmen. Wir haben eine Rechnung mit ihm zu begleichen.\"" },
      { number: 11, text: "Da zogen 3000 Judäer zur Felsspalte Etam und sagten zu Simson: \"Weißt du denn nicht, dass die Philister über uns herrschen? Warum hast du uns in solche Gefahr gebracht?\" – \"Ich habe ihnen nur heimgezahlt, was sie mir angetan haben\", erwiderte Simson." },
      { number: 12, text: "Da sagten die Männer Judas: \"Wir sind hergekommen, um dich zu fesseln und den Philistern auszuliefern.\" – \"Schwört mir\", erwiderte Simson, \"dass ihr mir aber nichts weiter antut!\"" },
      { number: 13, text: "\"Nein, wir wollen dich nur fesseln und ausliefern\", sagten sie, \"töten wollen wir dich nicht!\" So ließ er sich von ihnen fesseln und aus der Felsspalte herausführen." },
      { number: 14, text: "Als er nach Lehi kam, liefen ihm die Philister mit großem Geschrei entgegen. Da kam der Geist Jahwes über ihn. Er zerriss die Stricke an seinen Armen, als wären es von Feuer versengte Flachsfäden. Die Fesseln fielen von seinen Händen." },
      { number: 15, text: "Dann fand er einen frischen Eselskinnbacken. Er hob ihn auf und erschlug tausend Mann damit." },
      { number: 16, text: "\"Mit einem Eselsknochen habe ich sie verprügelt\", sagte Simson, \"mit dem Kinnbacken eines Esels habe ich tausend Mann erschlagen.\"" },
      { number: 17, text: "Danach warf er den Knochen weg. Seitdem heißt der Ort Ramat-Lehi, Kinnbackenhöhe." },
      { number: 18, text: "Aber Simson war am Verdursten und rief Jahwe an: \"Du hast mir, deinem Diener, diesen großen Sieg geschenkt. Lass mich jetzt nicht vor Durst sterben und in die Hand dieser Unbeschnittenen fallen!\"" },
      { number: 19, text: "Da ließ Gott in einer Bodensenke bei Lehi einen Spalt entstehen, aus dem Wasser herausquoll. Simson trank davon, und seine Lebensgeister kehrten zurück; er lebte wieder auf. Die Quelle ist noch heute bei Lehi zu finden. Man nennt sie En-Hakore, Ruferquelle." },
      { number: 20, text: "Als die Philister das Land beherrschten, war Simson für 20 Jahre Richter in Israel." },
    ] },
    { number: 16, verses: [
      { number: 1, text: "Einmal kam Simson nach Gaza. Dort sah er eine Prostituierte und ging zu ihr ins Haus.", heading: "Simson und Delila" },
      { number: 2, text: "Bald erfuhr die ganze Stadt, dass Simson in Gaza sei. Da suchten die Philister nach ihm und legten sich die Nacht über am Stadttor auf die Lauer. Sie beschlossen: \"Solange es dunkel ist, unternehmen wir nichts. Morgen früh bringen wir ihn um.\"" },
      { number: 3, text: "Simson aber stand schon um Mitternacht auf, ging zum Stadttor, packte die beiden Torflügel und riss sie samt Pfosten und Riegel heraus. Dann nahm er sie auf seine Schultern und trug sie auf den Gipfel des Hügels, der in Richtung Hebron liegt." },
      { number: 4, text: "Einige Zeit später verliebte er sich in eine Frau aus dem Tal Sorek*. Sie hieß Delila.", footnotes: ["Sorek. Heute: Wadi es-Sarar, das ist der Oberlauf des Flusses Nahr Rubin, der in der Nähe Jerusalems entspringt, durch das judäische Hügelland fließt und 13 km südlich von Jaffa ins Mittelmeer mündet."] },
      { number: 5, text: "Da gingen die Fürsten der Philister zu ihr und sagten: \"Du kannst ihn verführen! Sieh zu, dass du herausbekommst, woher seine große Kraft kommt und was wir tun müssen, um ihn in unsere Gewalt zu bringen. Du bekommst dafür von jedem von uns 1100 Silberstücke*.\"", footnotes: ["1100 Silberstücke. Eine ungeheure Summe. Schon mit 70 Silberstücken konnte Abimelech eine Bande Männer anheuern (Richter 9,4), und der Levit, den Micha anstellte (Richter 17,10), erhielt ganze zehn Silberstücke im Jahr (dazu Nahrung und Kleidung)."] },
      { number: 6, text: "Delila fragte Simson: \"Willst du mir nicht anvertrauen, warum du so stark bist? Gibt es Fesseln, die du nicht zerreißen kannst?\"" },
      { number: 7, text: "\"Wenn man mich mit sieben frischen Bogensehnen fesseln würde, die noch nicht ausgetrocknet sind\", erwiderte Simson, \"werde ich schwach wie ein anderer Mensch sein.\"" },
      { number: 8, text: "Die Fürsten der Philister besorgten ihr sieben solcher Sehnen. Und Delila fesselte Simson damit," },
      { number: 9, text: "während einige Männer bei ihr in der Kammer lauerten. Doch als sie dann rief: \"Simson, die Philister!\", zerriss er die Sehnen wie Flachsfäden, wenn sie Feuer riechen. Er hatte ihr nicht preisgegeben, woher seine Kraft kam." },
      { number: 10, text: "Da warf Delila ihm vor: \"Du hast mich zum Narren gehalten und mir Lügen erzählt! Nun verrate mir doch, womit man dich fesseln kann!\"" },
      { number: 11, text: "\"Wenn man mich ganz fest mit neuen Stricken binden würde, die noch nie benutzt worden sind\", sagte Simson, \"würde ich schwach werden wie andere Menschen auch.\"" },
      { number: 12, text: "Da nahm Delila neue Stricke und fesselte Simson damit. Wieder lagen einige Männer bei ihr auf der Lauer. Doch als sie rief: \"Simson, die Philister!\", riss er die Stricke wie Flachsfäden von seinen Armen." },
      { number: 13, text: "Da sagte Delila: \"Immer hältst du mich zum Narren und erzählst mir Lügen! Nun verrate mir doch endlich, womit man dich fesseln kann!\" – \"Du musst meine sieben Haarflechten im Webstuhl einweben\", erwiderte Simson." },
      { number: 14, text: "Sie tat das, als er schlief, und klopfte sie mit dem Weberblatt fest ins Gewebe. Dann rief sie wieder: \"Simson, die Philister!\" Da fuhr er hoch und riss das ganze Gewebe samt Weberbaum heraus." },
      { number: 15, text: "\"Wie kannst du nur behaupten, dass du mich liebst!\", warf Delila ihm vor. \"Du vertraust mir ja nicht einmal! Dreimal hast du mich jetzt schon getäuscht und mir nicht verraten, woher deine große Kraft kommt.\"" },
      { number: 16, text: "Tag für Tag redete sie auf ihn ein und quälte ihn so sehr, dass ihm das ganze Leben verleidet war." },
      { number: 17, text: "Da öffnete er ihr sein Herz und sagte: \"Noch nie sind mir die Haare geschnitten worden. Ich bin nämlich von Geburt an ein Nasiräer Gottes. Würde man mir die Haare abschneiden, würde ich meine Kraft verlieren und schwach werden wie andere Menschen auch.\"" },
      { number: 18, text: "Delila merkte, dass er ihr jetzt alles offenbart hatte. Sie schickte jemand zu den Philisterfürsten und ließ ihnen ausrichten: \"Diesmal müsst ihr selbst herkommen, denn er hat mir alles anvertraut!\" Da kamen sie und brachten das versprochene Silber mit." },
      { number: 19, text: "Delila ließ Simson auf ihren Knien einschlafen. Dann winkte sie einen von den Männern herbei und ließ die sieben Haarflechten Simsons abschneiden. So fingen sie an, ihn zu bezwingen, und Simson verlor seine Kraft." },
      { number: 20, text: "Delila rief: \"Simson, die Philister!\" Simson fuhr aus dem Schlaf hoch und dachte: \"Ich werde auch diesmal davonkommen wie bisher und mich frei schütteln.\" Er wusste aber nicht, dass Jahwe nicht mehr mit ihm war." },
      { number: 21, text: "Da packten ihn die Philister, stachen ihm die Augen aus und brachten ihn nach Gaza ins Gefängnis. Dort legten sie ihm Doppelfesseln aus Bronze an und zwangen ihn, die Mühle zu drehen." },
      { number: 22, text: "Aber sein Haar begann langsam wieder zu wachsen." },
      { number: 23, text: "Nach einiger Zeit kamen die Fürsten der Philister zu einem großen Freudenfest zusammen. Sie wollten ihrem Gott Dagon* ein großes Opfer schlachten. Dabei sangen sie:\"Unserm Gott sei es gedankt, / Simson ist in unsrer Hand!\"", heading: "Simsons Tod", footnotes: ["Dagon. Semitischer Fruchtbarkeitsgott, der für das Getreidewachstum sorgen sollte."] },
      { number: 24, text: "Als das Volk Simson sah, rühmten sie ihren Gott und sangen:\"Unserm Gott sei es gedankt, / Simson ist in unsrer Hand! / Er verheerte unser Land, / streckte viele in den Sand.\"" },
      { number: 25, text: "Und als sie richtig in Stimmung waren, grölten sie: \"Ruft Simson her! Er soll uns vortanzen!\" Man brachte Simson herbei und stellte ihn zwischen die Säulen*. Und sie hatten ihren Spaß mit ihm.", footnotes: ["Säulen. Man hat einen Philister-Tempel mit einem langgezogenen Innenraum ausgegraben, der zwei dicht beieinanderstehende hölzerne Hauptsäulen besaß, die das Dach stützten."] },
      { number: 26, text: "Simson bat den Jungen, der ihn führte: \"Lass meine Hand kurz los. Ich möchte die Säulen betasten, die das Haus tragen, und mich ein wenig anlehnen.\"" },
      { number: 27, text: "Das Gebäude war voller Menschen, die zusahen, wie Simson verspottet wurde. Allein auf dem Flachdach saßen 3000 Männer und Frauen. Auch alle Fürsten der Philister waren da." },
      { number: 28, text: "Simson betete: \"Herr, Jahwe, denk doch an mich und gib mir nur noch einmal meine alte Kraft! Ich will mich an den Philistern rächen – nur eine Rache für meine beiden Augen!\"" },
      { number: 29, text: "Dann tastete Simson nach den beiden Mittelsäulen, auf denen das Dach ruhte, und stemmte sich gegen die eine mit der rechten und gegen die andere mit der linken Hand." },
      { number: 30, text: "\"Sollen die Philister mit mir sterben!\", rief er und riss die Säulen mit aller Kraft um. Da stürzte das ganze Haus über den Philistern und ihren Fürsten zusammen. Dabei starben mehr Menschen, als Simson in seinem ganzen Leben getötet hatte." },
      { number: 31, text: "Simsons Brüder und alle Männer im Haushalt seines Vaters holten seinen Leichnam und begruben ihn zwischen Zora und Eschtaol im Grab seines Vaters Manoach." },
    ] },
    { number: 17, verses: [
      { number: 1, text: "Im Gebirge Efraïm lebte ein Mann namens Micha.", heading: "17-21: Auswüchse des Abfalls von Gott\nMichas Privatheiligtum" },
      { number: 2, text: "Eines Tages sagte er zu seiner Mutter: \"Die 1100 Silberstücke, die dir gestohlen worden sind und wegen denen du vor meinen Ohren den Fluch ausgesprochen hast, die habe ich genommen. Das Silber ist bei mir.\" – \"O mein Sohn!\", rief da die Mutter, \"Jahwe segne dich!\"" },
      { number: 3, text: "Als Micha ihr die 1100 Silberstücke zurückgab, erklärte sie: \"Hiermit weihe ich das Geld Jahwe. Es soll ein geschnitztes Gottesbild davon gemacht werden, mit Silber belegt! Damit kommt es auch dir zugute.\"" },
      { number: 4, text: "Sie nahm 200 Silberstücke von dem Geld und ließ vom Goldschmied ein Gottesbild* aus Holz schnitzen und mit Silber belegen. Micha stellte die Figur bei sich auf.", footnotes: ["Gottesbild. Es ist nicht sicher zu entscheiden, ob es sich in dieser Geschichte um ein oder zwei Götzenbilder handelt."] },
      { number: 5, text: "So kam Micha zu einem eigenen Heiligtum. Er ließ auch ein Efod und einige Terafim* anfertigen und setzte dann einen von seinen Söhnen als Priester ein.", footnotes: ["Terafim. Abbilder oder Figuren von Schutzgeistern bzw. Hausgötzen, die auch zu Orakelzwecken benutzt wurden."] },
      { number: 6, text: "Damals gab es noch keinen König in Israel. Jeder tat, was er für richtig hielt." },
      { number: 7, text: "Ein junger Levit* aus der Sippe Juda wohnte zu dieser Zeit als Fremder im judäischen Bethlehem.", footnotes: ["Levit. Angehöriger des Stammes Levi, der während der Wüstenwanderung Israels von Gott zum Dienst am Heiligtum ausgewählt wurde."] },
      { number: 8, text: "Er verließ die Stadt, um sich an einem anderen Ort niederzulassen. Auf seinem Weg durch das Gebirge Efraïm kam er an Michas Haus vorbei." },
      { number: 9, text: "Micha sprach ihn an: \"Wo kommst du her?\" Der antwortete: \"Ich bin ein Levit aus dem judäischen Bethlehem und suche irgendwo ein Unterkommen.\"" },
      { number: 10, text: "Da sagte Micha zu ihm: \"Bleib doch bei mir und sei mein geistlicher Vater und mein Priester! Ich gebe dir jährlich zehn Silberstücke, dazu die Kleidung, die du brauchst und den Lebensunterhalt.\"" },
      { number: 11, text: "Der Levit willigte ein und blieb. Micha behandelte ihn wie einen seiner Söhne." },
      { number: 12, text: "Dann setzte er ihn feierlich als Priester ein und" },
      { number: 13, text: "dachte: \"Jetzt bin ich sicher, dass Jahwe mir Gutes tun wird, denn ich habe ja einen Leviten zum Priester.\"" },
    ] },
    { number: 18, verses: [
      { number: 1, text: "Damals gab es noch keinen König in Israel. Der Stamm Dan war gerade dabei, sich ein eigenes Wohngebiet zu suchen, denn bis dahin war ihm noch kein Eigentum innerhalb der Stämme Israels zugefallen.", heading: "Die Kundschafter aus Dan" },
      { number: 2, text: "Deshalb wählten die Daniten fünf Männer aus ihrer Mitte aus, die das Land auskundschaften sollten. Es waren tüchtige Leute aus Zora und Eschtaol, die den Auftrag erhielten, das Land zu erforschen. Sie kamen ins Gebirge Efraïm zum Haus Michas und übernachteten dort." },
      { number: 3, text: "Dabei fiel ihnen der Levit durch seinen Dialekt auf. Sie gingen zu ihm und fragten: \"Wie bist du hierher gekommen? Was machst du hier und was hast du hier verloren?\"" },
      { number: 4, text: "Der junge Mann erzählte ihnen seine Geschichte. \"Micha hat mich in Lohn und Brot genommen, und so bin ich sein Priester geworden\", schloss er." },
      { number: 5, text: "Da baten sie ihn: \"Frag doch Gott für uns, ob unsere Reise Erfolg haben wird.\"" },
      { number: 6, text: "Der Priester sagte ihnen: \"Zieht in Frieden weiter! Jahwe ist mit eurer Reise einverstanden.\"" },
      { number: 7, text: "Die fünf Männer zogen weiter und kamen nach Lajisch*. Sie sahen, dass die Menschen dort ruhig und sorglos wie die Sidonier lebten. Es gab niemand, der sie im Land bedroht hätte. Die Sidonier waren weit entfernt*, und sie lebten ganz für sich.", footnotes: ["Lajisch. Ort an einem der Quellflüsse des Jordan, später Dan. Siehe Josua 19,47-48.", "weit entfernt. Von Phönizien waren die Bewohner von Lajisch durch den Gebirgszug des Libanon getrennt und von Syrien durch den Hermon und den Antilibanon."] },
      { number: 8, text: "Als die Kundschafter nach Zora und Eschtaol zurückkehrten, fragten ihre Stammesbrüder: \"Was bringt ihr?\"" },
      { number: 9, text: "Sie erwiderten: \"Auf, lasst uns über sie herfallen! Wir haben das Land gesehen, es ist wirklich sehr gut. Was steht ihr noch herum? Los, machen wir uns auf den Weg und nehmen das Land in Besitz!" },
      { number: 10, text: "Ihr werdet ein sorgloses Volk vorfinden und ein geräumiges Land, wo es alles gibt, was ihr euch vorstellen könnt. Gott hat es in eure Hand gegeben!\"" },
      { number: 11, text: "Mit 600 bewaffneten Männern brachen die Daniten von Zora und Eschtaol auf.", heading: "Ein Stamm raubt ein Heiligtum" },
      { number: 12, text: "Ihr erstes Lager schlugen sie bei Kirjat-Jearim* im Gebiet des Stammes Juda auf. Deshalb nennt man diesen Ort westlich von Kirjat-Jearim bis heute Mahane-Dan, Lager Dans.", footnotes: ["Kirjat-Jearim. 11 km westlich von Jerusalem an der Grenze zu Benjamin."] },
      { number: 13, text: "Die Daniten zogen von dort weiter ins Gebirge Efraïm und kamen auch an Michas Ansiedlung vorbei." },
      { number: 14, text: "Da sagten die fünf Kundschafter zu ihren Stammesbrüdern: \"Wisst ihr, dass es in diesen Häusern ein Efod und Terafim gibt und außerdem ein geschnitztes, mit Silber überzogenes Gottesbild? Bedenkt, was das für eine Gelegenheit ist!\"" },
      { number: 15, text: "Da bogen sie vom Weg ab und die Kundschafter gingen zum Haus des Leviten, das zum Besitz Michas gehörte, und begrüßten ihn." },
      { number: 16, text: "Aber die 600 bewaffneten Daniten blieben vor dem Tor stehen." },
      { number: 17, text: "Als dann der Levit zu ihnen herausgekommen war und bei ihnen stand, gingen die Kundschafter ins Haus und nahmen das Gottesbild, das Efod und die Terafim an sich." },
      { number: 18, text: "Als der Priester sah, dass sie in Michas Haus eindrangen, sagte er zu ihnen: \"Was macht ihr da?\"" },
      { number: 19, text: "\"Sei still! Halt den Mund und zieh mit uns!\", gaben sie zurück. \"Du sollst der geistliche Vater und Priester für uns werden! Ist es denn besser für dich, Hauspriester für eine Familie oder der Priester für einen ganzen Stamm und ein Geschlecht in Israel zu sein?\"" },
      { number: 20, text: "Das gefiel dem Priester gut. Er nahm das Efod, die Terafim und das Schnitzbild und schloss sich den Daniten an." },
      { number: 21, text: "Beim Weitermarsch ließen sie ihre Kinder, das Vieh und ihren wertvollen Besitz an die Spitze des Zuges bringen." },
      { number: 22, text: "Sie hatten sich schon ein Stück vom Haus Michas entfernt, als sie von ihm und den Männern eingeholt wurden, die er aus der Nachbarschaft aufgetrieben hatte." },
      { number: 23, text: "Sie schrien den Daniten hinterher. Die drehten sich um und sagten zu Micha: \"Warum machst du ein solches Geschrei?\"" },
      { number: 24, text: "\"Ihr habt mir meine Götter weggenommen\", rief er, \"und den Priester dazu! Ihr habt mich ausgeraubt! Da fragt ihr noch, was los ist!\"" },
      { number: 25, text: "Aber die Daniten entgegneten ihm: \"Belästige uns nicht mit deinem Geschrei! Sonst bekommst du es mit erbitterten Leuten zu tun. Das würde dich und deine Männer das Leben kosten.\"" },
      { number: 26, text: "Dann setzten sie ihren Weg fort. Micha sah, dass er gegen ihre Übermacht nichts ausrichten konnte, und kehrte nach Hause zurück." },
      { number: 27, text: "So nahmen die Daniten mit, was Micha sich hatte anfertigen lassen, und auch seinen Priester. Dann überfielen sie die Einwohner von Lajisch, die ruhig und sorglos dahinlebten. Sie erschlugen sie mit dem Schwert und brannten ihre Stadt nieder." },
      { number: 28, text: "Niemand konnte den Leuten von Lajisch zu Hilfe kommen, denn Sidon war zu weit entfernt. Sie lebten ganz für sich. Die Stadt lag nämlich in der Ebene von Bet-Rechob*. Die Daniten bauten sie wieder auf,", footnotes: ["Bet-Rechob. Zwischen dem Berg Hermon und dem Libanon-Gebirge."] },
      { number: 29, text: "nannten die Stadt aber nicht mehr Lajisch, sondern gaben ihr den Namen ihres Stammvaters Dan, der ein Sohn von Israel* gewesen war.", footnotes: ["Israel. Das heißt von Jakob, der später Israel genannt wurde, siehe 1. Mose 32,29."] },
      { number: 30, text: "Dort stellten sie das geschnitzte Gottesbild auf und machten Jonathan, der von Moses Sohn Gerschom abstammte, zu ihrem Priester. Auch seine Söhne versahen den Priesterdienst für die Daniten, bis die Bewohner der ganzen Gegend in die Gefangenschaft geführt wurden." },
      { number: 31, text: "Sie stellten sich also das Schnitzbild Michas auf und verehrten es so lange, wie auch das Heiligtum von Schilo* Bestand hatte.", footnotes: ["Schilo. Heute: Seilon, 30 km nördlich von Jerusalem. Dort wurde die Stiftshütte aufgestellt und durch feste Bauwerke ergänzt. Diese wurden vermutlich nach der Schlacht bei Afek um 1050 v.Chr. zerstört (siehe 1. Samuel 4,10)."] },
    ] },
    { number: 19, verses: [
      { number: 1, text: "Zu dieser Zeit, als es in Israel noch keinen König gab, lebte ganz im Norden des Gebirges Efraïm ein Levit, der sich eine Nebenfrau aus Bethlehem genommen hatte.", heading: "Der Schwiegervater" },
      { number: 2, text: "Doch diese wurde ihm untreu und ging fremd. Dann lief sie ihm weg und kehrte ins Haus ihres Vaters nach Bethlehem zurück. Vier Monate später" },
      { number: 3, text: "machte ihr Mann sich auf, um mit ihr zu sprechen und sie zurückzugewinnen. Er hatte seinen Diener, einen jungen Mann, mitgenommen und zwei Esel. Die junge Frau brachte ihn zu ihrem Vater ins Haus. Als dieser ihn sah, kam er ihm freudig entgegen." },
      { number: 4, text: "Sein Schwiegervater wollte ihn gar nicht wieder gehen lassen. So blieben sie drei Tage da, aßen, tranken und übernachteten bei ihm." },
      { number: 5, text: "Am vierten Tag standen sie früh auf, um sich auf den Weg zu machen. Da sagte der Vater der jungen Frau zu seinem Schwiegersohn: \"Iss doch noch eine Kleinigkeit und stärke dich für den Weg! Dann könnt ihr gehen.\"" },
      { number: 6, text: "So setzten sich die beiden Männer hin und aßen und tranken. \"Tu mir doch den Gefallen\", sagte der Schwiegervater dann, \"und bleib noch eine Nacht. Lass es dir bei mir gut gehen!\"" },
      { number: 7, text: "Doch der Levit erhob sich, um zu gehen. Sein Schwiegervater aber drängte ihn, dass er doch noch eine Nacht blieb." },
      { number: 8, text: "Am fünften Tag stand der Levit wieder früh auf, um sich auf den Weg zu machen. Da sagte der Vater der jungen Frau: \"Stärke dich doch erst noch und bleibt hier, bis der Tag kühler wird!\" So aßen sie noch einmal miteinander." },
      { number: 9, text: "Dann erhob sich der Levit, um sich mit seiner Frau und seinem Diener auf den Weg zu machen. Doch der Vater der jungen Frau versuchte es noch einmal: \"Schau, es wird schon wieder Abend. Übernachte doch noch einmal. Bleib noch eine Nacht und lass es dir wohl sein. Morgen früh könnt ihr dann aufbrechen und nach Hause zurückkehren.\"" },
      { number: 10, text: "Aber der Levit wollte nicht noch einmal übernachten. Er stand auf und machte sich mit seiner Nebenfrau und den beiden gesattelten Eseln auf den Heimweg." },
      { number: 11, text: "Als sie nach Jebus, dem heutigen Jerusalem, kamen, war der Tag schon fast zu Ende gegangen. Da sagte der junge Mann zu seinem Herrn: \"Lass uns doch in die Jebusiterstadt hier gehen und dort übernachten!\"", heading: "Nachtquartier gesucht" },
      { number: 12, text: "Doch sein Herr erwiderte: \"Nein, wir kehren nicht bei Fremden ein, die keine Israeliten sind. Lasst uns nach Gibea* hinübergehen!", footnotes: ["Gibea. 6 km nördlich von Jerusalem; war später Heimat und Regierungssitz von König Saul."] },
      { number: 13, text: "Wenn wir uns beeilen, können wir Gibea oder sogar Rama* erreichen und dort übernachten.\"", footnotes: ["Rama war noch 3 km weiter entfernt."] },
      { number: 14, text: "So zogen sie weiter. Als sie in die Nähe von Gibea gekommen waren, das zu Benjamin gehört, ging ihnen die Sonne unter." },
      { number: 15, text: "Da bogen sie vom Weg ab und betraten die Stadt. Doch es gab niemand, der sie zum Übernachten in sein Haus aufgenommen hätte. So ließen sie sich auf dem Marktplatz nieder." },
      { number: 16, text: "Es war schon Abend, da kam ein alter Mann von seiner Feldarbeit nach Hause. Er stammte vom Gebirge Efraïm und lebte als Fremder unter den Benjaminiten im Ort." },
      { number: 17, text: "Als er den Wanderer im Freien rasten sah, sprach er ihn an: \"Wohin gehst du und woher kommst du?\"" },
      { number: 18, text: "\"Wir kommen aus dem judäischen Bethlehem und wollen an das andere Ende des Gebirges Efraïm. Ich stamme von dort und habe eine Reise nach Bethlehem in Juda unternommen und bin jetzt auf dem Rückweg nach Hause. Aber hier in Gibea will uns niemand aufnehmen," },
      { number: 19, text: "obwohl wir Stroh und Futter für die Esel und Brot und Wein für uns, deine Diener, mitgenommen haben, für mich, die Frau und den jungen Mann hier. Wir sind wirklich mit allem versorgt.\"" },
      { number: 20, text: "Da sagte der alte Mann: \"Schalom, seid mir willkommen! Lasst mich für euch sorgen und übernachtet nicht hier auf dem Platz!\"" },
      { number: 21, text: "Er führte sie in sein Haus und schüttete den Eseln Futter vor. Dann wuschen sie ihre Füße und aßen und tranken miteinander." },
      { number: 22, text: "Während sie noch fröhlich beisammen saßen, umstellten plötzlich die Männer der Stadt das Haus. Es war ein übles Gesindel. Sie trommelten gegen die Tür und schrien nach dem alten Mann, dem Hausherrn: \"Los, bring uns den Mann heraus, der bei dir ist! Wir wollen es mit ihm treiben!\"", heading: "Das Verbrechen von Gibea" },
      { number: 23, text: "Da ging der alte Mann, der Besitzer des Hauses, zu ihnen hinaus und sagte: \"Nein, meine Brüder, so etwas Schändliches dürft ihr nicht tun! Der Mann ist doch mein Gast!" },
      { number: 24, text: "Eher gebe ich euch meine unberührte Tochter heraus, und dazu die Nebenfrau des Fremden, damit ihr sie vergewaltigen könnt. Macht mit ihnen, was ihr wollt! Aber diesem Mann dürft ihr nicht so etwas Schändliches antun!\"" },
      { number: 25, text: "Doch die Männer wollten nicht auf ihn hören. Da packte der Mann seine Nebenfrau und brachte sie zu ihnen hinaus. Sie fielen über sie her und vergewaltigten sie die ganze Nacht. Erst als der Tag anbrach, ließen sie von ihr ab." },
      { number: 26, text: "Die Frau schleppte sich noch bis zum Eingang des Hauses, in dem ihr Mann war, und brach dort zusammen. So lag sie, bis es hell wurde." },
      { number: 27, text: "Als der Mann am Morgen aus der Tür trat, um weiterzuziehen, sah er die Frau, seine Nebenfrau. Sie lag am Eingang des Hauses, die ausgestreckten Hände auf der Schwelle." },
      { number: 28, text: "\"Steh auf\", sagte er zu ihr, \"wir müssen weiter!\" Aber er bekam keine Antwort. Da lud er sie auf den Esel und reiste nach Hause." },
      { number: 29, text: "Dort angekommen, nahm er ein Messer, zerteilte den Leichnam seiner Frau in zwölf Stücke und schickte diese im ganzen Gebiet Israels herum." },
      { number: 30, text: "Jeder, der so ein Stück sah, sagte: \"Solch ein Verbrechen hat es in Israel noch nie gegeben, seit unsere Vorfahren aus Ägypten hierher gekommen sind. Bedenkt das und überlegt genau, was ihr jetzt tun müsst!\"" },
    ] },
    { number: 20, verses: [
      { number: 1, text: "Da versammelten sich alle Männer Israels von Dan bis Beerscheba und ganz Gilead* in Mizpa*. Sie erschienen wie ein Mann vor Jahwe.", heading: "Das Böse muss beseitigt werden", footnotes: ["Gilead. Das meint ganz Israel vom Norden bis zum Süden und dazu das Ostjordanland.", "Mizpa. 12 km nördlich von Jerusalem, nicht zu verwechseln mit dem Mizpa von Kapitel 10,17."] },
      { number: 2, text: "Die Oberhäupter des ganzen Volkes traten zusammen und nahmen ihren Platz in der Versammlung aller Stämme Israels ein. 400.000 mit Schwertern bewaffnete Männer hatten sich zusammengefunden." },
      { number: 3, text: "Auch die Benjaminiten erfuhren von dem Treffen in Mizpa. Die versammelten Israeliten fragten nun: \"Wie ist dieses Verbrechen geschehen?\"" },
      { number: 4, text: "Da berichtete der Levit, dessen Frau ermordet worden war: \"Ich kam mit meiner Nebenfrau nach Gibea, das zu Benjamin gehört, um dort zu übernachten." },
      { number: 5, text: "In der Nacht umringten die Männer der Stadt das Haus meines Gastgebers. Sie hatten es aber auf mich abgesehen. Mich wollten sie umbringen, und meine Nebenfrau haben sie so vergewaltigt, dass sie gestorben ist." },
      { number: 6, text: "Da zerteilte ich ihren Leichnam und schickte die Stücke durch ganz Israel. Jeder sollte sehen, was für ein abscheuliches Verbrechen in unserem Land begangen wurde." },
      { number: 7, text: "Nun seid ihr alle hier, ihr Israeliten: Bildet euch eine Meinung und schafft Rat!\"" },
      { number: 8, text: "Da standen sie alle auf wie ein Mann und erklärten: \"Keiner von uns darf nach Hause zurückkehren," },
      { number: 9, text: "bevor wir die Strafe an den Leuten von Gibea vollstreckt haben. Wir wollen das Los werfen," },
      { number: 10, text: "und jeder zehnte Mann soll sich um die Verpflegung für die anderen kümmern, damit wir gleich nach Gibea in Benjamin ziehen können, um ihre Bewohner für dieses schändliche Verbrechen zu bestrafen." },
      { number: 11, text: "So zogen die Israeliten wie ein Mann gegen die Stadt." },
      { number: 12, text: "Gleichzeitig hatten sie Boten an den Stamm Benjamin geschickt, die ihnen ausrichten sollten: \"Was ist da für eine schreckliche Untat unter euch begangen worden!" },
      { number: 13, text: "Liefert uns die Männer von Gibea aus! Wir werden dieses gottlose Gesindel töten und so das Böse aus Israel entfernen.\" Doch die Benjaminiten wollten nicht auf ihre Brüder, die Israeliten, hören." },
      { number: 14, text: "Sie kamen aus ihren Städten nach Gibea, um gegen die Israeliten zu kämpfen." },
      { number: 15, text: "Noch am selben Tag stellten sie ein Heer von 26.000 mit Schwertern bewaffneten Männern auf. Dazu kamen noch die Männer von Gibea, 700 geübte Krieger." },
      { number: 16, text: "Im Heer Benjamins gab es 700 Elitekämpfer, die sogar mit der linken Hand Steine schleudern konnten und ihr Ziel nie verfehlten." },
      { number: 17, text: "Die Israeliten hatten 400.000 mit Schwertern bewaffnete geübte Krieger aufgeboten." },
      { number: 18, text: "Dann zogen die Israeliten nach Bet-El, um Gott zu fragen, wer von ihnen zuerst gegen die Benjaminiten in den Kampf ziehen sollte. Jahwe antwortete: \"Juda soll anfangen!\"", heading: "Der Sieg der Benjaminiten" },
      { number: 19, text: "Am nächsten Morgen machten sich die Israeliten auf, zogen vor Gibea" },
      { number: 20, text: "und stellten sich zum Kampf gegen die Männer von Benjamin." },
      { number: 21, text: "Da stürmten die Benjaminiten heraus und streckten an jenem Tag 22.000 Mann von ihnen zu Boden.*", footnotes: ["Gibea lag auf einem Hügel und war sehr gut zu verteidigen."] },
      { number: 22, text: "Doch die Männer Israels fassten Mut und stellten sich noch einmal an der gleichen Stelle zum Kampf, wo sie am ersten Tag gestanden hatten." },
      { number: 23, text: "Sie waren nämlich wieder nach Bet-El gezogen und hatten bis zum Abend vor Jahwe über ihre Niederlage geweint. Dann hatten sie Jahwe befragt, ob sie wieder in den Kampf gegen die Benjaminiten, ihre Brüder, ziehen sollten. Jahwe hatte geantwortet: \"Ja, zieht gegen sie!\"" },
      { number: 24, text: "Am zweiten Tag rückten sie wieder gegen die Männer von Benjamin vor." },
      { number: 25, text: "Doch die Benjaminiten brachen erneut aus der Stadt hervor und erschlugen noch einmal 18.000 Israeliten, alles mit dem Schwert bewaffnete Kämpfer." },
      { number: 26, text: "Da zogen die Männer Israels wieder ab und gingen nach Bet-El hinauf. Dort saßen sie klagend vor Jahwe. Sie fasteten jenen Tag bis zum Abend und brachten Jahwe dann Brand- und Freudenopfer*.", footnotes: ["Beim Freudenopfer (wörtlich Friedens- oder Heilsopfer) durfte der größte Teil des Tieres bei einer fröhlichen Opfermahlzeit gemeinsam mit Verwandten und Freunden verzehrt werden."] },
      { number: 27, text: "Dann befragten sie Jahwe, denn die Bundeslade Jahwes war damals gerade dort" },
      { number: 28, text: "und Pinhas Ben-Eleasar, der Enkel Aarons, diente als Priester. Sie fragten: \"Sollen wir noch einmal gegen unsere Brüder in den Kampf ziehen, gegen die Männer aus Benjamin, oder sollen wir es aufgeben? Da sagte Jahwe: \"Ja, zieht hin! Morgen gebe ich sie in eure Hand.\"" },
      { number: 29, text: "Darauf legten die Israeliten rings um Gibea Leute in den Hinterhalt", heading: "Ein Stamm fast ausgelöscht" },
      { number: 30, text: "und stellten sich wie an den anderen Tagen zum Kampf gegen die Benjaminiten auf." },
      { number: 31, text: "Wieder brachen die Benjaminiten aus der Stadt hervor und erschlugen wie die vorigen Male einige von den Israeliten. Dabei entfernten sie sich immer weiter von der Stadt in Richtung Bet-El und Gibeon*. Sie hatten schon etwa 30 Mann auf dem freien Feld erschlagen", footnotes: ["Gibeon. 9 km nordwestlich von Jerusalem und 6 km von Gibea entfernt."] },
      { number: 32, text: "und riefen: \"Wir schlagen sie wie beim ersten Mal!\" Aber die Israeliten hatten verabredet: Lasst uns fliehen, damit wir sie von der Stadt zu den Landstraßen weglocken." },
      { number: 33, text: "So gingen die Männer Israels zurück und ordneten sich bei Baal-Tamar* neu. Gleichzeitig brachen die Männer aus dem Hinterhalt westlich von Gibea hervor.", footnotes: ["Baal-Tamar. Ort an der Grenze zwischen Juda und Benjamin, dicht bei Gibea."] },
      { number: 34, text: "Es waren 10.000 aus ganz Israel ausgesuchte Krieger. Sie gingen gegen die Stadt vor, und es kam zu einem schweren Kampf. Die anderen Benjaminiten ahnten nicht, dass das Unglück sie schon erreicht hatte." },
      { number: 35, text: "An diesem Tag tötete Jahwe durch die Israeliten 25.100 bewaffnete Kämpfer aus dem Stamm Benjamin." },
      { number: 36, text: "Schließlich mussten die Benjaminiten einsehen, dass sie geschlagen waren.Der Kampf war so verlaufen: Die Israeliten hatten den Benjaminiten Raum gegeben, weil sie sich auf den Hinterhalt verließen, den sie in der Nähe der Stadt gelegt hatten." },
      { number: 37, text: "Die Männer des Hinterhalts stürmten auf Gibea zu und eroberten die Stadt. Alle Bewohner töteten sie mit dem Schwert." },
      { number: 38, text: "Sie hatten mit den Israeliten vereinbart, dass sie dann eine Rauchwolke aus der Stadt aufsteigen lassen wollten." },
      { number: 39, text: "Als nun die Mannschaft Israels vor den Benjaminiten zurückwich, hatten diese angefangen, einige von ihnen zu erschlagen, etwa 30 Mann. Sie riefen: \"Wir werden sie besiegen wie im ersten Kampf!\"" },
      { number: 40, text: "Doch da begann eine Wolke aus der Stadt aufzusteigen, die zu einer Rauchsäule wurde. Und als die Benjaminiten sich umschauten, sahen sie, dass die ganze Stadt wie ein Ganzopfer in Flammen aufgegangen war." },
      { number: 41, text: "Da machten auch die Israeliten wieder kehrt und stellten sich zum Kampf. Die Männer Benjamins waren entsetzt und merkten, dass sie verloren waren." },
      { number: 42, text: "Da versuchten sie, vor den Israeliten in Richtung Wüste zu fliehen, aber die Schlacht holte sie ein. Und die israelitischen Männer, die aus Gibea kamen, nahmen sie in die Zange." },
      { number: 43, text: "So umzingelten die Israeliten die Benjaminiten. Sie verfolgten sie ohne Rast bis östlich von Gibea und machten sie nieder." },
      { number: 44, text: "Auf diese Weise fielen 18.000 benjaminitische Krieger." },
      { number: 45, text: "Der Rest versuchte weiter in Richtung Wüste zum Felsen Rimmon* zu fliehen. Doch die Israeliten schlugen auf den Straßen noch einmal 5000 Mann nieder und bei der weiteren Verfolgung noch einmal 2000 Mann.", footnotes: ["Rimmon. Der Felsen liegt 18 km nordöstlich von Jerusalem und ist auf drei Seiten durch tiefe Täler von der Umgebung abgeschnitten. Die Höhlen dort konnten 600 Männern monatelang Schutz und Unterkunft bieten."] },
      { number: 46, text: "So waren an diesem Tag 25.000 bewaffnete Benjaminiten gefallen, alles tapfere Krieger." },
      { number: 47, text: "Nur 600 Mann erreichten den Felsen Rimmon und verschanzten sich dort vier Monate lang." },
      { number: 48, text: "Die Israeliten aber zogen durch das ganze Stammesgebiet von Benjamin und töteten alle Menschen und Tiere, die sie fanden, und brannten alle Ortschaften nieder." },
    ] },
    { number: 21, verses: [
      { number: 1, text: "In Mizpa hatten die Israeliten geschworen: \"Keiner von uns wird jemals seine Tochter einem Benjaminiten zur Frau geben!\"", heading: "Benjamin darf nicht untergehen" },
      { number: 2, text: "Und nun kamen sie nach Bet-El und saßen bis zum Abend klagend vor Gott. Weinend sagten sie:" },
      { number: 3, text: "\"O Jahwe, du Gott Israels, warum musste das geschehen? Ein ganzer Stamm fehlt heute in Israel.\"" },
      { number: 4, text: "Am nächsten Morgen in aller Frühe baute das Volk einen Altar und brachte Brand- und Freudenopfer auf ihm dar." },
      { number: 5, text: "Dann fragten die Israeliten: \"Wer ist dem Aufruf an alle Stämme Israels zur Versammlung vor Jahwe nicht gefolgt?\" Sie hatten nämlich einen feierlichen Eid geschworen: \"Wer nicht zu Jahwe nach Mizpa heraufkommt, wird unbedingt mit dem Tod bestraft!\"" },
      { number: 6, text: "Den Israeliten tat es sehr leid um ihren Bruderstamm Benjamin. \"Heute ist ein ganzer Stamm von Israel abgehauen worden!\", sagten sie." },
      { number: 7, text: "\"Wie können wir den Überlebenden nur zu Frauen verhelfen? Wir haben ja vor Jahwe geschworen, dass keiner von uns seine Tochter einem von ihnen zur Frau gibt.\"" },
      { number: 8, text: "Deshalb fragten sie: \"Wer ist dem Aufruf an alle Stämme Israels, zu Jahwe nach Mizpa heraufzukommen, nicht gefolgt?\" Da stellte man fest, dass niemand von Jabesch in Gilead* in die Versammlung gekommen war,", footnotes: ["Jabesch lag 15 km südöstlich von Bet-Schean im Ostjordanland."] },
      { number: 9, text: "denn als sie ihre Truppen musterten, fehlten die Männer aus Jabesch." },
      { number: 10, text: "Da schickte die Versammlung 12.000 Mann nach Jabesch mit dem Auftrag, alle Einwohner der Stadt mit dem Schwert zu töten, auch die Frauen und Kinder:" },
      { number: 11, text: "\"An jedem Mann und an jeder Frau, die schon mit einem Mann geschlafen hat, sollt ihr den Bann vollstrecken!\"" },
      { number: 12, text: "Die Männer Israels fanden unter den Bewohnern von Jabesch in Gilead 400 unberührte Mädchen, mit denen noch kein Mann geschlafen hatte, und brachten sie ins Lager nach Schilo im Land Kanaan." },
      { number: 13, text: "Dann schickte die ganze Versammlung Boten zu den Männern Benjamins, die sich noch am Felsen Rimmon aufhielten, und machten ihnen ein Friedensangebot." },
      { number: 14, text: "So kehrten die 600 Männer zurück und bekamen die Mädchen, die die Israeliten in Jabesch am Leben gelassen hatten. Aber es waren nicht genug für sie alle." },
      { number: 15, text: "Das Volk hatte Mitleid mit Benjamin, weil Jahwe eine Lücke in die Stämme Israels gerissen hatte.", heading: "Frauenraub in Schilo" },
      { number: 16, text: "\"Was können wir nur tun, um den Übriggebliebenen zu Frauen zu verhelfen?\", fragten die Ältesten. \"In Benjamin ist ja keine Frau am Leben geblieben.\"" },
      { number: 17, text: "Und sie beschlossen: \"Der Besitz der Überlebenden muss bei Benjamin bleiben, denn es darf kein Stamm aus Israel aussterben." },
      { number: 18, text: "Wir können ihnen aber keine von unseren Töchtern zur Frau geben, denn wir alle haben feierlich geschworen: 'Wer einem Mann aus Benjamin eine Frau gibt, sei verflucht!'\"" },
      { number: 19, text: "Schließlich meinten sie: \"Es gibt doch jedes Jahr ein Fest Jahwes in Schilo.\" – Schilo liegt nördlich von Bet-El und östlich der Straße, die von Bet-El nach Sichem hochführt, und südlich von Lebona*. –", footnotes: ["Lebona. Kleiner Ort 5 km nördlich von Schilo, das zur Zeit der Abfassung des Buches zerstört war."] },
      { number: 20, text: "Und sie forderten die Männer Benjamins auf: \"Legt euch in den Weinbergen dort auf die Lauer!" },
      { number: 21, text: "Wenn dann die Mädchen aus Schilo zum Reigentanz herauskommen, dann fange sich jeder eine Frau und nehme sie mit in seine Heimat." },
      { number: 22, text: "Wenn ihre Väter und Brüder sich dann bei uns beschweren, werden wir ihnen sagen: 'Lasst ihnen die Mädchen, uns zuliebe! Wir konnten im Krieg gegen Jabesch nicht für jeden von ihnen eine Frau gewinnen. Und ihr habt euch auch nicht schuldig gemacht, denn ihr habt sie ihnen ja nicht selbst gegeben.\"" },
      { number: 23, text: "Die Benjaminiten gingen auf den Vorschlag ein, und jeder raubte sich eine Frau von den tanzenden Mädchen. Dann kehrten sie in ihren Erbbesitz zurück, bauten die Städte wieder auf und wohnten darin." },
      { number: 24, text: "Nun zogen auch die Israeliten wieder heim, jeder zu seinem Stamm, seiner Sippe und seinem Erbbesitz." },
      { number: 25, text: "Damals gab es noch keinen König in Israel. Jeder tat, was er für richtig hielt." },
    ] },
  ],
};